import React, { useState, useEffect } from 'react';
import { Search, Loader2, X } from 'lucide-react';

interface InventorySearchBarProps {
  onSearch: (query: string) => void;
  placeholder?: string;
  initialValue?: string;
}

const InventorySearchBar: React.FC<InventorySearchBarProps> = ({ 
  onSearch, 
  placeholder = "Search inventory...", 
  initialValue = ""
}) => {
  const [value, setValue] = useState(initialValue);
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    // Debounce logic
    setIsSearching(true);
    const handler = setTimeout(() => {
      onSearch(value);
      setIsSearching(false);
    }, 500);

    return () => {
      clearTimeout(handler);
    };
  }, [value, onSearch]);

  const handleClear = () => {
    setValue('');
    onSearch('');
  };

  return (
    <div className="relative w-full">
      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-chocolate-400">
        {isSearching ? (
          <Loader2 className="w-5 h-5 animate-spin text-primary" />
        ) : (
          <Search className="w-5 h-5" />
        )}
      </div>
      
      <input
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={placeholder}
        className="w-full pl-12 pr-10 py-3.5 bg-white border border-chocolate-100 rounded-xl shadow-sm 
                   focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary 
                   text-gray-900 placeholder-chocolate-300 transition-all text-base"
      />

      {value && (
        <button
          onClick={handleClear}
          className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-chocolate-400 hover:text-chocolate-600 rounded-full hover:bg-chocolate-50 transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      )}
    </div>
  );
};

export default InventorySearchBar;

import React, { useState, useRef, useEffect } from 'react';
import {
  Menu,
  Bell,
  Search,
  User,
  LogOut,
  Candy,
  ChevronDown,
  Settings,
  HelpCircle,
  X
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import { cn } from '../../lib/utils';

interface NavbarProps {
  onMobileMenuToggle: () => void;
  notificationCount?: number;
}

const Navbar: React.FC<NavbarProps> = ({ onMobileMenuToggle, notificationCount = 0 }) => {
  const { useCurrentUser, useLogout } = useAuth();
  const { data: user } = useCurrentUser();
  const logout = useLogout();
  const navigate = useNavigate();

  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const userMenuRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userMenuRef.current && !userMenuRef.current.contains(event.target as Node)) {
        setIsUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Focus search input when mobile search opens
  useEffect(() => {
    if (isSearchOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isSearchOpen]);

  // Handle logout
  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  // Handle search submit
  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchQuery)}`);
      setSearchQuery('');
      setIsSearchOpen(false);
    }
  };

  // Capitalize role for display
  const displayRole = user?.role
    ? user.role.split('_').map((word: string) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')
    : '';

  // Get user initials
