    expires_at: '',
    is_active: true
  });
  const [showPreview, setShowPreview] = useState(false);

  const { mutate: createAnnouncement, isPending: isCreating } = useCreateAnnouncement();
  const { mutate: updateAnnouncement, isPending: isUpdating } = useUpdateAnnouncement();

  const allRoles: UserRole[] = ['admin', 'manager', 'production_worker', 'warehouse_worker', 'quality_controller', 'mechanic'];

  useEffect(() => {
    if (announcement) {
      setFormData({ // eslint-disable-line
        title: announcement.title || '',
        content: announcement.content || '',
        priority: announcement.priority || 'normal',
        target_roles: announcement.target_roles || [],
        expires_at: announcement.expires_at ? new Date(announcement.expires_at).toISOString().split('T')[0] : '',
        is_active: announcement.is_active ?? true
      });
    } else {
      setFormData({
        title: '',
        content: '',
        priority: 'normal',
        target_roles: [],
        expires_at: '',
        is_active: true
      });
    }
  }, [announcement]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim() || !formData.content.trim()) {
      toast.error('Title and content are required');
      return;
    }

    if (formData.target_roles.length === 0) {
      toast.error('Please select at least one target role');
      return;
    }

    const data = {
      ...formData,
      expires_at: formData.expires_at || undefined
    };

    if (announcement) {
      updateAnnouncement({ id: announcement.id, ...data }, {
        onSuccess: () => {
          toast.success('Announcement updated successfully');
          onSuccess();
          onClose();
        },
        onError: (error: any) => {
          toast.error(error.message || 'Failed to update announcement');
        }
      });
    } else {
      createAnnouncement(data, {
        onSuccess: () => {
          toast.success('Announcement published successfully');
          onSuccess();
          onClose();
        },
        onError: (error: any) => {
          toast.error(error.message || 'Failed to publish announcement');
        }
      });
    }
  };

  const toggleRole = (role: UserRole) => {
    setFormData(prev => ({
      ...prev,
      target_roles: prev.target_roles.includes(role)
        ? prev.target_roles.filter(r => r !== role)
        : [...prev.target_roles, role]
    }));
  };

  const toggleAllRoles = () => {
    setFormData(prev => ({
      ...prev,
      target_roles: prev.target_roles.length === allRoles.length ? [] : [...allRoles]
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-gradient-to-r from-amber-500 to-orange-500 text-white p-6 rounded-t-2xl flex items-center justify-between">
          <h2 className="text-2xl font-bold">
            {announcement ? 'Edit Announcement' : 'Create New Announcement'}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-white/20 rounded-lg transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6">
          {!showPreview ? (
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Title */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Title *
                </label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                  className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-amber-500 focus:outline-none"
                  placeholder="Enter announcement title"
                  required
                />
              </div>

              {/* Content */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Content *
                </label>
                <textarea
                  value={formData.content}
                  onChange={(e) => setFormData(prev => ({ ...prev, content: e.target.value }))}
                  rows={6}
                  className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-amber-500 focus:outline-none resize-none"
                  placeholder="Enter announcement content"
                  required
                />
              </div>

              {/* Priority */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Priority
                </label>
                <div className="grid grid-cols-3 gap-3">
                  {(['normal', 'high', 'urgent'] as const).map((priority) => (
                    <button
                      key={priority}
                      type="button"
                      onClick={() => setFormData(prev => ({ ...prev, priority: priority as Announcement['priority'] }))}
                      className={`px-4 py-2 rounded-lg font-medium transition-all ${
                        formData.priority === priority
                          ? priority === 'urgent'
                            ? 'bg-red-500 text-white'
                            : priority === 'high'
                            ? 'bg-amber-500 text-white'
                            : 'bg-gray-500 text-white'
                          : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                      }`}
                    >
                      {priority.charAt(0).toUpperCase() + priority.slice(1)}
                    </button>
                  ))}
                </div>
              </div>

              {/* Target Roles */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="block text-sm font-medium text-gray-700">
                    Target Roles *
                  </label>
                  <button
                    type="button"
                    onClick={toggleAllRoles}
                    className="text-sm text-amber-600 hover:text-amber-700 font-medium"
                  >
                    {formData.target_roles.length === allRoles.length ? 'Deselect All' : 'Select All'}
                  </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {allRoles.map((role) => (
                    <label
                      key={role}
                      className="flex items-center gap-2 p-3 border-2 border-gray-200 rounded-lg cursor-pointer hover:bg-amber-50 transition-colors"
                    >
                      <input
                        type="checkbox"
                        checked={formData.target_roles.includes(role)}
                        onChange={() => toggleRole(role)}
                        className="w-4 h-4 text-amber-600 border-gray-300 rounded focus:ring-amber-500"
                      />
                      <span className="text-sm font-medium text-gray-700">
                        {role.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                      </span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Expiry Date */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Expiry Date (Optional)
                </label>
                <input
                  type="date"
                  value={formData.expires_at}
                  onChange={(e) => setFormData(prev => ({ ...prev, expires_at: e.target.value }))}
                  min={new Date().toISOString().split('T')[0]}
                  className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-amber-500 focus:outline-none"
                />
              </div>

               <div className="flex items-center gap-3">
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData(prev => ({ ...prev, is_active: e.target.checked }))}
                    className="sr-only peer"
                  />
                  <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-amber-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-amber-600"></div>
                </label>
                <span className="text-sm font-medium text-gray-700">
                  {formData.is_active ? 'Active' : 'Inactive'}
                </span>
              </div>

              {/* Buttons */}
              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowPreview(true)}
                  className="flex-1 px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium flex items-center justify-center gap-2"
                >
                  <Eye className="w-5 h-5" />
                  Preview
                </button>
                <button
                  type="submit"
                  disabled={isCreating || isUpdating}
                  className="flex-1 px-6 py-3 bg-gradient-to-r from-amber-500 to-orange-500 text-white rounded-lg hover:from-amber-600 hover:to-orange-600 transition-all font-medium disabled:opacity-50"
                >
                  {isCreating || isUpdating ? 'Saving...' : announcement ? 'Update' : 'Publish'}
                </button>
              </div>
            </form>
          ) : (
            <div className="space-y-6">
              {/* Preview */}
              <div className="bg-gradient-to-br from-amber-50 to-orange-50 rounded-xl p-6 border-2 border-amber-200">
                <div className="flex items-start gap-3 mb-4">
                  <h3 className="text-2xl font-bold text-gray-900 flex-1">
                    {formData.title}
                  </h3>
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                    formData.priority === 'urgent'
                      ? 'bg-red-100 text-red-700'
                      : formData.priority === 'high'
                      ? 'bg-amber-100 text-amber-700'
                      : 'bg-gray-100 text-gray-700'
                  }`}>
                    {formData.priority.toUpperCase()}
                  </span>
                </div>
                
                <p className="text-gray-700 whitespace-pre-wrap mb-4">
                  {formData.content}
                </p>

                <div className="flex flex-wrap gap-2">
                  {formData.target_roles.map((role) => (
                    <span
                      key={role}
                      className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-medium"
                    >
                      {role.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                    </span>
                  ))}
                </div>
              </div>

              <button
                onClick={() => setShowPreview(false)}
                className="w-full px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
              >
                Back to Edit
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AnnouncementModal;

import { useState } from 'react';
import { useBatchTranslate } from '../../services/aiService';
import { Button } from '../ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card';
import { Loader2, Mic, Languages } from 'lucide-react';
import { toast } from 'sonner';

export function BroadcastTranslator() {
  const [instructions, setInstructions] = useState('');
  const [targetLanguages, setTargetLanguages] = useState<string[]>(['ar', 'am', 'ru']);
  const { mutateAsync: translateAsync, isPending, data } = useBatchTranslate();

  const handleBroadcast = async () => {
    if (!instructions.trim()) {
      toast.error("Please enter instructions first");
      return;
    }

    try {
        toast.info(`Broadcasting to ${targetLanguages.length} teams...`);
        
        const promises = targetLanguages.map(lang => 
            translateAsync({
                texts: [instructions],
                targetLanguage: lang,
                context: { domain: 'instruction' }
            }).then(res => {
                toast.success(`Sent to ${lang.toUpperCase()} team: ${res.translations[0].substring(0, 20)}...`);
                return res;
            })
        );

        await Promise.all(promises);
    } catch {
        toast.error("Some broadcasts failed. Check console.");
    }
  };

  const toggleLanguage = (lang: string) => {
    setTargetLanguages(prev => 
      prev.includes(lang) 
        ? prev.filter(l => l !== lang)
        : [...prev, lang]
    );
  };

  return (
    <Card className="border-cocoa-100 bg-white">
      <CardHeader className="pb-3 border-b border-cocoa-50">
        <CardTitle className="text-lg font-bold flex items-center gap-2 text-cocoa-900">
          <Languages className="h-5 w-5 text-gold-600" />
          Broadcast Shift Instructions
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-4 space-y-4">
        <div className="relative">
          <textarea
            value={instructions}
            onChange={(e) => setInstructions(e.target.value)}
            placeholder="Write instructions in Hebrew or English (e.g., 'Check cocoa powder inventory')..."
            className="w-full h-24 p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-gold-500 focus:border-transparent resize-none text-sm"
          />
          <Button 
            variant="ghost" 
            size="sm" 
            className="absolute right-2 bottom-2 text-slate-400 hover:text-gold-600"
          >
            <Mic className="h-4 w-4" />
          </Button>
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">
            Broadcast To:
          </label>
          <div className="flex flex-wrap gap-2">
            {[
              { code: 'ar', label: '≡ƒç╕≡ƒçª Arabic' },
              { code: 'he', label: '≡ƒç«≡ƒç▒ Hebrew' },
              { code: 'am', label: '≡ƒç¬≡ƒç╣ Amharic' },
              { code: 'ru', label: '≡ƒç╖≡ƒç║ Russian' },
              { code: 'uk', label: '≡ƒç║≡ƒçª Ukrainian' }
            ].map(lang => (
              <button
                key={lang.code}
                onClick={() => toggleLanguage(lang.code)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors border ${
                  targetLanguages.includes(lang.code)
                    ? 'bg-gold-50 border-gold-200 text-gold-800'
                    : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'
                }`}
              >
                {lang.label} {targetLanguages.includes(lang.code) && 'Γ£ô'}
              </button>
            ))}
          </div>
        </div>

        <Button 
          onClick={() => void handleBroadcast()} 
          disabled={isPending || !instructions.trim() || targetLanguages.length === 0}
          className="w-full bg-slate-900 hover:bg-slate-800 text-white"
        >
          {isPending ? (
            <>
              <Loader2 className="h-4 w-4 me-2 animate-spin" /> Translating & Sending...
            </>
          ) : (
            '≡ƒôó Broadcast to All Workers'
          )}
        </Button>

        {data && targetLanguages.length > 0 && (
          <div className="bg-slate-50 rounded-lg p-3 border border-slate-100 animate-fade-in">
            <p className="text-xs font-medium text-slate-500 mb-2">
              Live Preview ({targetLanguages[0].toUpperCase()}):
            </p>
            <p dir="auto" className="text-sm font-medium text-slate-800">
              {data.translations[0]}
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useMemo } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  ReferenceLine,
  Area,
  AreaChart,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card';
import { TrendingUp, PieChart as PieChartIcon, BarChart3, Activity } from 'lucide-react';
import { cn } from '../../lib/utils';

interface AnalyticsData {
  productionTrends?: {
    date: string;
    started: number;
    completed: number;
  }[];
  qcTrends?: {
    date: string;
    rate: number;
  }[];
  inventoryStatus?: {
    adequate: number;
    lowStock: number;
    expired: number;
  };
  batchStatus?: {
    pending: number;
    mixing: number;
    cooking: number;
    cooling: number;
    packaging: number;
    completed: number;
    failed: number;
  };
  [key: string]: any;
}

interface ChartsSectionProps {
  analytics?: AnalyticsData;
  loading?: boolean;
}

// Chocolate-themed color palette
const COLORS = {
  primary: '#8B4513', // Saddle Brown (cocoa)
  secondary: '#D2691E', // Chocolate
  tertiary: '#CD853F', // Peru
  success: '#22c55e', // Green
  warning: '#f59e0b', // Amber
  danger: '#ef4444', // Red
  info: '#3b82f6', // Blue
  purple: '#8b5cf6', // Purple
  gray: '#6b7280', // Gray
};

const BATCH_COLORS = {
  pending: '#9ca3af',
  mixing: '#3b82f6',
  cooking: '#f97316',
  cooling: '#06b6d4',
  packaging: '#8b5cf6',
  completed: '#22c55e',
  failed: '#ef4444',
};

const INVENTORY_COLORS = {
  adequate: '#22c55e',
  lowStock: '#f59e0b',
  expired: '#ef4444',
};

// Generate mock data for demonstration
const generateMockProductionData = () => {
  const data = [];
  const today = new Date();
  for (let i = 29; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    data.push({
      date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      started: Math.floor(Math.random() * 15) + 5,
      completed: Math.floor(Math.random() * 12) + 3,
    });
  }
  return data;
};

const generateMockQCData = () => {
  const data = [];
  const today = new Date();
  for (let i = 29; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    data.push({
      date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      rate: Math.floor(Math.random() * 15) + 82, // 82-97%
    });
  }
  return data;
};

const ChartsSection: React.FC<ChartsSectionProps> = ({
  analytics,
  loading = false,
}) => {
  // Use analytics data or mock data
  const productionData = useMemo(() =>
    analytics?.productionTrends ?? generateMockProductionData(),
    [analytics?.productionTrends]
  );

  const qcData = useMemo(() =>
    analytics?.qcTrends ?? generateMockQCData(),
    [analytics?.qcTrends]
  );

  const inventoryData = useMemo(() => {
    const status = analytics?.inventoryStatus ?? {
      adequate: 120,
      lowStock: 25,
      expired: 8,
    };
    return [
      { name: 'Adequate', value: status.adequate, color: INVENTORY_COLORS.adequate },
      { name: 'Low Stock', value: status.lowStock, color: INVENTORY_COLORS.lowStock },
      { name: 'Expired', value: status.expired, color: INVENTORY_COLORS.expired },
    ];
  }, [analytics?.inventoryStatus]);

  const batchData = useMemo(() => {
    const status = analytics?.batchStatus ?? {
      pending: 5,
      mixing: 3,
      cooking: 4,
      cooling: 2,
      packaging: 3,
      completed: 45,
      failed: 2,
    };
    return [
      { name: 'Pending', value: status.pending, color: BATCH_COLORS.pending },
      { name: 'Mixing', value: status.mixing, color: BATCH_COLORS.mixing },
      { name: 'Cooking', value: status.cooking, color: BATCH_COLORS.cooking },
      { name: 'Cooling', value: status.cooling, color: BATCH_COLORS.cooling },
      { name: 'Packaging', value: status.packaging, color: BATCH_COLORS.packaging },
      { name: 'Completed', value: status.completed, color: BATCH_COLORS.completed },
      { name: 'Failed', value: status.failed, color: BATCH_COLORS.failed },
    ].filter(item => item.value > 0);
  }, [analytics?.batchStatus]);

  // Calculate totals for center display
  const inventoryTotal = inventoryData.reduce((sum, item) => sum + item.value, 0);
  const batchTotal = batchData.reduce((sum, item) => sum + item.value, 0);

  // Custom tooltip styles
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div className="bg-white p-3 border border-slate-200 rounded-lg shadow-lg">
          <p className="text-sm font-medium text-slate-700 mb-1">{label}</p>
          {payload.map((entry: any, index: number) => (
            <p key={index} className="text-sm" style={{ color: entry.color }}>
              {entry.name}: {entry.value}
              {entry.name === 'Rate' ? '%' : ''}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  // Loading skeleton
  const ChartSkeleton = () => (
    <div className="h-64 bg-gradient-to-br from-slate-100 to-slate-50 rounded-lg animate-pulse flex items-center justify-center">
      <Activity className="w-8 h-8 text-slate-300 animate-pulse" />
    </div>
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Production Trend Chart */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="flex items-center gap-2 text-base">
            <TrendingUp className="w-5 h-5 text-cocoa-600" />
            Production Trend (30 Days)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <ChartSkeleton />
          ) : (
            <ResponsiveContainer width="100%" height={280}>
              <AreaChart data={productionData} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorStarted" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={COLORS.info} stopOpacity={0.3} />
                    <stop offset="95%" stopColor={COLORS.info} stopOpacity={0} />
                  </linearGradient>
                  <linearGradient id="colorCompleted" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={COLORS.success} stopOpacity={0.3} />
                    <stop offset="95%" stopColor={COLORS.success} stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="date"
                  tick={{ fontSize: 11 }}
                  tickLine={false}
                  interval="preserveStartEnd"
                />
                <YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} />
                <Tooltip content={<CustomTooltip />} />
                <Legend wrapperStyle={{ fontSize: '12px' }} />
                <Area
                  type="monotone"
                  dataKey="started"
                  name="Started"
                  stroke={COLORS.info}
                  fillOpacity={1}
                  fill="url(#colorStarted)"
                  strokeWidth={2}
                />
                <Area
                  type="monotone"
                  dataKey="completed"
                  name="Completed"
                  stroke={COLORS.success}
                  fillOpacity={1}
                  fill="url(#colorCompleted)"
                  strokeWidth={2}
                />
              </AreaChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

      {/* QC Approval Rate Chart */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="flex items-center gap-2 text-base">
            <BarChart3 className="w-5 h-5 text-green-600" />
            QC Approval Rate (30 Days)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <ChartSkeleton />
          ) : (
            <ResponsiveContainer width="100%" height={280}>
              <LineChart data={qcData} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="date"
                  tick={{ fontSize: 11 }}
                  tickLine={false}
                  interval="preserveStartEnd"
                />
                <YAxis
                  tick={{ fontSize: 11 }}
                  tickLine={false}
                  axisLine={false}
                  domain={[70, 100]}
                  tickFormatter={(value) => `${value}%`}
                />
                <Tooltip content={<CustomTooltip />} />
                <ReferenceLine
                  y={90}
                  stroke={COLORS.warning}
                  strokeDasharray="5 5"
                  label={{ value: 'Target 90%', fontSize: 10, fill: COLORS.warning }}
                />
                <Line
                  type="monotone"
                  dataKey="rate"
                  name="Rate"
                  stroke={COLORS.success}
                  strokeWidth={2}
                  dot={false}
                  activeDot={{ r: 6, fill: COLORS.success }}
                />
              </LineChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

