import React, { useMemo } from 'react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine,
} from 'recharts';
import { Card, CardContent } from '../ui/Card';
import { QCStats, DefectAnalysis } from '../../types';

interface QCChartsSectionProps {
  stats: QCStats;
  defectAnalysis?: DefectAnalysis;
}

const QCChartsSection: React.FC<QCChartsSectionProps> = ({
  stats,
  defectAnalysis,
}) => {
  // Prepare approval rate trend data (last 7 days)
  const approvalTrendData = useMemo(() => {
    if (!stats.approvalTrend) {
      // Mock data if not available
      const today = new Date();
      return Array.from({ length: 7 }, (_, i) => {
        const date = new Date(today);
        date.setDate(date.getDate() - (6 - i));
        return {
          date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          approvalRate: 85 + Math.random() * 10,
          target: 90,
        };
      });
    }
    return stats.approvalTrend;
  }, [stats.approvalTrend]);

  // Prepare defects by type data
  const defectsData = useMemo(() => {
    if (!defectAnalysis?.defectsByType) {
      // Mock data if not available
      return [
        { type: 'Discoloration', count: 12 },
        { type: 'Cracks', count: 8 },
        { type: 'Air bubbles', count: 15 },
        { type: 'Uneven coating', count: 6 },
        { type: 'Blooming', count: 4 },
      ];
    }
    return defectAnalysis.defectsByType.slice(0, 5); // Top 5
  }, [defectAnalysis]);

  // Prepare quality scores over time
  const qualityScoresData = useMemo(() => {
    if (!stats.qualityScoresTrend) {
      const today = new Date();
      return Array.from({ length: 7 }, (_, i) => {
        const date = new Date(today);
        date.setDate(date.getDate() - (6 - i));
        return {
          date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          appearance: 4 + Math.random(),
          texture: 4 + Math.random(),
          taste: 4 + Math.random(),
        };
      });
    }
    return stats.qualityScoresTrend;
  }, [stats.qualityScoresTrend]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Approval Rate Trend */}
      <Card>
        <CardContent className="p-6">
            <h3 className="text-lg font-bold text-chocolate-800 mb-4">
            Approval Rate Trend (Last 7 Days)
            </h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                <LineChart data={approvalTrendData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                    <XAxis
                    dataKey="date"
                    stroke="#78350F"
                    style={{ fontSize: '12px' }}
                    tickLine={false}
                    axisLine={false}
                    />
                    <YAxis
                    stroke="#78350F"
                    style={{ fontSize: '12px' }}
                    domain={[0, 100]}
                    tickLine={false}
                    axisLine={false}
                    tickFormatter={(val) => `${val}%`}
                    />
                    <Tooltip
                    contentStyle={{
                        backgroundColor: '#FFF',
                        border: '1px solid #D4A574',
                        borderRadius: '8px',
                        boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                    }}
                    />
                    <Legend wrapperStyle={{ paddingTop: '10px' }} />
                    <ReferenceLine
                    y={90}
                    stroke="#10B981"
                    strokeDasharray="3 3"
                    label={{ value: 'Target: 90%', position: 'right', fill: '#10B981', fontSize: 12 }}
                    />
                    <Line
                    type="monotone"
                    dataKey="approvalRate"
                    stroke="#78350F"
                    strokeWidth={3}
                    dot={{ fill: '#78350F', r: 4, strokeWidth: 0 }}
                    activeDot={{ r: 6 }}
                    name="Approval Rate"
                    />
                </LineChart>
                </ResponsiveContainer>
            </div>
        </CardContent>
      </Card>

      {/* Defects by Type */}
      <Card>
        <CardContent className="p-6">
            <h3 className="text-lg font-bold text-chocolate-800 mb-4">
            Top 5 Defects by Type
            </h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                <BarChart data={defectsData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                    <XAxis 
                        type="number" 
                        stroke="#78350F" 
                        style={{ fontSize: '12px' }}
                        tickLine={false}
                        axisLine={false}
                    />
                    <YAxis 
                        dataKey="type" 
                        type="category" 
                        stroke="#78350F" 
                        style={{ fontSize: '12px' }} 
                        width={100}
                        tickLine={false}
                        axisLine={false}
                    />
                    <Tooltip
                    cursor={{ fill: '#f8fafc' }}
                    contentStyle={{
                        backgroundColor: '#FFF',
                        border: '1px solid #D4A574',
                        borderRadius: '8px',
                        boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                    }}
                    />
                    <Bar 
                        dataKey="count" 
                        fill="#DC2626" 
                        name="Defect Count" 
                        radius={[0, 4, 4, 0]}
                        barSize={20}
                    />
                </BarChart>
                </ResponsiveContainer>
            </div>
        </CardContent>
      </Card>

      {/* Quality Scores Over Time */}
      <Card className="lg:col-span-2">
        <CardContent className="p-6">
            <h3 className="text-lg font-bold text-chocolate-800 mb-4">
            Quality Scores Trend (Last 7 Days)
            </h3>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                <LineChart data={qualityScoresData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                    <XAxis
                    dataKey="date"
                    stroke="#78350F"
                    style={{ fontSize: '12px' }}
                    tickLine={false}
                    axisLine={false}
                    />
                    <YAxis
                    stroke="#78350F"
                    style={{ fontSize: '12px' }}
                    domain={[0, 5]}
                    tickLine={false}
                    axisLine={false}
                    />
                    <Tooltip
                    contentStyle={{
                        backgroundColor: '#FFF',
                        border: '1px solid #D4A574',
                        borderRadius: '8px',
                        boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                    }}
                    />
                    <Legend wrapperStyle={{ paddingTop: '10px' }} />
                    <Line
                    type="monotone"
                    dataKey="appearance"
                    stroke="#3B82F6"
                    strokeWidth={2}
                    dot={{ fill: '#3B82F6', r: 3, strokeWidth: 0 }}
                    name="Appearance"
                    />
                    <Line
                    type="monotone"
                    dataKey="texture"
                    stroke="#10B981"
                    strokeWidth={2}
                    dot={{ fill: '#10B981', r: 3, strokeWidth: 0 }}
                    name="Texture"
                    />
                    <Line
                    type="monotone"
                    dataKey="taste"
                    stroke="#F59E0B"
                    strokeWidth={2}
                    dot={{ fill: '#F59E0B', r: 3, strokeWidth: 0 }}
                    name="Taste"
                    />
                </LineChart>
                </ResponsiveContainer>
            </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default QCChartsSection;

import React from 'react';
import {
  X,
  Star,
  User,
  Calendar,
  ThermometerSun,
  Droplets,
  AlertTriangle,
  Package,
  FileText,
} from 'lucide-react';
import { Modal } from '../common/Modal';
import { Badge } from '../ui/Badge';
import { useQC } from '../../hooks/useQC';

interface QCDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  qcCheckId: string;
}

const QCDetailModal: React.FC<QCDetailModalProps> = ({
  isOpen,
  onClose,
  qcCheckId,
}) => {
  const { useQCCheck } = useQC();
  
  const { data: qcData, isLoading, error } = useQCCheck(qcCheckId);

  const qc = qcData;

  const getResultBadge = (result: string) => {
    switch (result) {
      case 'approved':
        return { variant: 'success' as const, label: 'Approved', icon: 'Γ£à' };
      case 'rejected':
        return { variant: 'error' as const, label: 'Rejected', icon: 'Γ¥î' };
      case 'quarantine':
        return { variant: 'warning' as const, label: 'Quarantine', icon: 'ΓÜá∩╕Å' };
      default:
        return { variant: 'default' as const, label: result, icon: 'Γ¥ô' };
    }
  };

  const StarDisplay: React.FC<{ score: number; label: string }> = ({
    score,
    label,
  }) => (
    <div className="bg-chocolate-50 p-4 rounded-lg">
      <p className="text-sm font-medium text-chocolate-700 mb-2">{label}</p>
      <div className="flex items-center gap-2">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`w-6 h-6 ${
              star <= score
                ? 'text-gold-500 fill-gold-500'
                : 'text-chocolate-200'
            }`}
          />
        ))}
        <span className="ml-2 text-xl font-bold text-chocolate-800">
          {score}/5
        </span>
      </div>
    </div>
  );

  if (isLoading) {
    return (
      <Modal isOpen={isOpen} onClose={onClose} title="QC Inspection Details">
        <div className="space-y-4 animate-pulse p-4">
          <div className="h-6 bg-chocolate-200 rounded w-3/4"></div>
          <div className="h-4 bg-chocolate-200 rounded w-1/2"></div>
          <div className="h-32 bg-chocolate-200 rounded"></div>
          <div className="h-32 bg-chocolate-200 rounded"></div>
        </div>
      </Modal>
    );
  }

  if (error || !qc) {
    return (
      <Modal isOpen={isOpen} onClose={onClose} title="QC Inspection Details">
        <div className="text-center py-8">
          <p className="text-red-600 mb-4">Error loading QC details</p>
          <p className="text-sm text-chocolate-600">
            {error?.message || 'QC check not found'}
          </p>
        </div>
      </Modal>
    );
  }

  const resultBadge = getResultBadge(qc.result);

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={`QC Inspection #${qc.id}`} size="lg">
      <div className="space-y-6">
        {/* Header Info */}
        <div className="bg-chocolate-50 border border-chocolate-200 rounded-lg p-4">
          <div className="flex items-center justify-between mb-3">
            <div>
              <p className="text-sm text-chocolate-600">Inspection ID: #{qc.id}</p>
              <div className="flex items-center gap-2 text-sm text-chocolate-600 mt-1">
                <Calendar className="w-4 h-4" />
                {new Date(qc.checked_at).toLocaleString()}
              </div>
            </div>
            
             {/* Result Badge - Large and Prominent */}
            <div className="text-center">
              <div className="text-4xl mb-1">{resultBadge.icon}</div>
              <Badge variant={resultBadge.variant} className="text-base px-4 py-1">
                {resultBadge.label}
              </Badge>
            </div>
          </div>
        </div>

        {/* Batch Information */}
        <div className="border border-chocolate-200 rounded-lg p-4">
          <div className="flex items-center gap-2 mb-3">
            <Package className="w-5 h-5 text-chocolate-600" />
            <h3 className="font-semibold text-chocolate-800">
              Batch Information
            </h3>
          </div>
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <p className="text-chocolate-600">Batch Number</p>
              <p className="font-semibold text-chocolate-800 font-mono">
                {qc.batch_number}
              </p>
            </div>
            {qc.recipe_name && (
              <div>
                <p className="text-chocolate-600">Recipe</p>
                <p className="font-semibold text-chocolate-800">
                  {qc.recipe_name}
                </p>
              </div>
            )}
            <div>
                 <p className="text-chocolate-600">Inspector</p>
                 <div className="flex items-center gap-2 mt-1">
                    <User className="w-4 h-4 text-gray-400" />
                    <span className="font-semibold text-chocolate-800">{qc.inspector_name}</span>
                 </div>
            </div>
          </div>
        </div>

        {/* Quality Scores */}
        <div className="border border-chocolate-200 rounded-lg p-4">
          <h3 className="font-semibold text-chocolate-800 mb-4">
            Quality Scores
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <StarDisplay score={qc.appearance_score || 0} label="Appearance" />
            <StarDisplay score={qc.texture_score || 0} label="Texture" />
            <StarDisplay score={qc.taste_score || 0} label="Taste" />
          </div>
          <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg text-center">
            <p className="text-sm text-blue-700">
              <span className="font-semibold">Average Score: </span>
              {(((qc.appearance_score || 0) + (qc.texture_score || 0) + (qc.taste_score || 0)) / 3).toFixed(2)}
              /5
            </p>
          </div>
        </div>

        {/* Environmental & Defects Split */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Environmental Data */}
            {(qc.temperature || qc.humidity) && (
            <div className="border border-chocolate-200 rounded-lg p-4 h-full">
                <h3 className="font-semibold text-chocolate-800 mb-4 flex items-center gap-2">
                    <ThermometerSun className="w-5 h-5" /> Environment
                </h3>
                <div className="space-y-4">
                {qc.temperature && (
                    <div className="bg-chocolate-50 p-3 rounded-lg flex justify-between items-center">
                        <span className="text-sm font-medium text-chocolate-700">Temperature</span>
                        <span className="text-lg font-bold text-chocolate-800">{qc.temperature}┬░C</span>
                    </div>
                )}
                {qc.humidity && (
                    <div className="bg-chocolate-50 p-3 rounded-lg flex justify-between items-center">
                         <span className="text-sm font-medium text-chocolate-700">Humidity</span>
                        <span className="text-lg font-bold text-chocolate-800">{qc.humidity}%</span>
                    </div>
                )}
                </div>
            </div>
            )}

            {/* Defects Section */}
            <div className="border border-chocolate-200 rounded-lg p-4 h-full">
            <div className="flex items-center gap-2 mb-3">
                <AlertTriangle className="w-5 h-5 text-chocolate-600" />
                <h3 className="font-semibold text-chocolate-800">Defects</h3>
            </div>
            <div className="mb-3">
                <p className="text-sm text-chocolate-600">Total Count</p>
                <p
                className={`text-2xl font-bold ${
                    qc.defect_count > 0 ? 'text-red-600' : 'text-green-600'
                }`}
                >
                {qc.defect_count}
                </p>
            </div>
            {qc.defect_types && qc.defect_types.length > 0 && (
                <div>
                <p className="text-sm text-chocolate-600 mb-2">Defect Types:</p>
                <div className="flex flex-wrap gap-2">
                    {qc.defect_types.map((defect, index: number) => (
                    <Badge key={index} variant="error">
                        {defect.type} ({defect.count})
                    </Badge>
                    ))}
                </div>
                </div>
            )}
            </div>
        </div>

        {/* Notes */}
        {qc.notes && (
          <div className="border border-chocolate-200 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-3">
              <FileText className="w-5 h-5 text-chocolate-600" />
              <h3 className="font-semibold text-chocolate-800">Notes</h3>
            </div>
            <p className="text-chocolate-700 whitespace-pre-wrap">{qc.notes}</p>
          </div>
        )}
      </div>
    </Modal>
  );
};

export default QCDetailModal;

import React, { useState } from 'react';
import { Eye, Star, ExternalLink } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import QCDetailModal from './QCDetailModal';
import { QCCheck } from '../../types';

interface QCHistoryTableProps {
  qcChecks: QCCheck[];
  loading: boolean;
}

const QCHistoryTable: React.FC<QCHistoryTableProps> = ({
  qcChecks,
  loading,
}) => {
  const navigate = useNavigate();
  const [selectedQCId, setSelectedQCId] = useState<string | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);

  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffDays > 0) return `${diffDays}d ago`;
    if (diffHours > 0) return `${diffHours}h ago`;
    if (diffMins > 0) return `${diffMins}m ago`;
    return 'Just now';
  };

  const getResultVariant = (result: string) => {
    switch (result) {
      case 'approved': return 'success';
      case 'rejected': return 'error';
      case 'quarantine': return 'warning';
      default: return 'default';
    }
  };

  const getResultLabel = (result: string) => {
      switch (result) {
        case 'approved': return 'Approved';
        case 'rejected': return 'Rejected';
        case 'quarantine': return 'Quarantine';
        default: return result;
      }
    };

  const getRowColor = (result: string) => {
    switch (result) {
      case 'approved':
        return 'hover:bg-green-50/50';
      case 'rejected':
        return 'hover:bg-red-50/50';
      case 'quarantine':
        return 'hover:bg-amber-50/50';
      default:
        return 'hover:bg-chocolate-50/50';
    }
  };

  const handleViewQC = (qcId: string) => {
    setSelectedQCId(qcId);
    setIsDetailModalOpen(true);
  };

  const ScoreDisplay: React.FC<{ score: number }> = ({ score }) => (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((star) => (
        <Star
          key={star}
          className={`w-3.5 h-3.5 ${
            star <= score
              ? 'text-gold-500 fill-gold-500'
              : 'text-chocolate-200'
          }`}
        />
      ))}
      <span className="ml-1 text-sm font-medium text-chocolate-700">
        {score}
      </span>
    </div>
  );

  if (loading) {
    return (
      <div className="overflow-x-auto p-6">
        <div className="space-y-4 animate-pulse">
             {[...Array(5)].map((_, i) => (
                 <div key={i} className="h-12 bg-gray-100 rounded-lg w-full"></div>
             ))}
        </div>
      </div>
    );
  }

  if (qcChecks.length === 0) {
    return (
      <div className="p-12 text-center">
        <Eye className="w-16 h-16 text-chocolate-300 mx-auto mb-4" />
        <h3 className="text-lg font-semibold text-chocolate-800 mb-2">
          No inspections yet
        </h3>
        <p className="text-chocolate-600">
          Submit your first QC inspection using the form above
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-chocolate-50 border-b border-chocolate-200">
            <tr>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
