  Wifi,
  WifiOff
} from 'lucide-react';
import { cn } from '../../lib/utils';
import { aiService, MULTILINGUAL_PHRASES, detectLanguage, useGetAIStatus } from '../../services/aiService';

type SupportedLanguage = 'en' | 'am' | 'ru' | 'he' | 'ar';

interface ChatMessage {
  id: string;
  content: string;
  isUser: boolean;
  timestamp: Date;
  language?: string;
}

const languages = [
  { code: 'en', label: 'EN', fullLabel: 'ENGLISH' },
  { code: 'am', label: 'AM', fullLabel: 'ßèáßê¢ßê¡ßè¢' },
  { code: 'ru', label: 'RU', fullLabel: '╨á╨ú╨í╨í╨Ü╨ÿ╨Ö' },
  { code: 'he', label: 'HE', fullLabel: '╫ó╫æ╫¿╫Ö╫¬' },
  { code: 'ar', label: 'AR', fullLabel: '╪º┘ä╪╣╪▒╪¿┘è╪⌐' },
];

const quickActions = [
  { icon: TrendingUp, label: 'Production Status', query: 'What is the current production status?' },
  { icon: AlertCircle, label: 'Low Stock Alerts', query: 'Show me low stock inventory items' },
  { icon: Brain, label: 'AI Recommendations', query: 'Give me optimization recommendations' },
  { icon: MessageSquare, label: 'Quality Report', query: 'Generate a quality control summary' },
];

const AIAssistantPage: React.FC = () => {
  const [inputValue, setInputValue] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedLang, setSelectedLang] = useState<SupportedLanguage>('en');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Get AI provider status
  const { data: aiStatus } = useGetAIStatus();
  const provider = aiStatus?.provider ?? 'demo';
  const isOnline = provider !== 'demo' && provider !== 'offline' && provider !== 'mock';

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  // Focus input on mount
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleSendMessage = useCallback(async (messageText?: string) => {
    const text = messageText ?? inputValue.trim();
    if (!text || isLoading) return;

    setError(null);
    const detectedLang = detectLanguage(text) as SupportedLanguage;

    // Add user message
    const userMessage: ChatMessage = {
      id: `user-${Date.now()}`,
      content: text,
      isUser: true,
      timestamp: new Date(),
      language: detectedLang
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    // Use auto-detected language from user input for natural conversation
    const responseLanguage = detectedLang ?? selectedLang;

    try {
      const response = await aiService.sendChatMessage({
        message: text,
        language: responseLanguage,
        context: { user_role: 'OPERATOR' }
      });

      const aiMessage: ChatMessage = {
        id: `ai-${Date.now()}`,
        content: response.message ?? response.response ?? 'Response received.',
        isUser: false,
        timestamp: new Date(response.timestamp ?? Date.now()),
        language: responseLanguage
      };

      setMessages(prev => [...prev, aiMessage]);
    } catch (err: unknown) {
      console.error('AI Chat Error:', err);
      const errorMsg = err instanceof Error ? err.message : 'Network Error';
      if (err && typeof err === 'object' && 'response' in err) {
        const axiosErr = err as { response?: { data?: { message?: string } } };
        setError(axiosErr.response?.data?.message ?? errorMsg);
      } else {
        setError(errorMsg);
      }

      const errorMessage: ChatMessage = {
        id: `error-${Date.now()}`,
        content: MULTILINGUAL_PHRASES[responseLanguage]?.error ?? MULTILINGUAL_PHRASES.en.error,
        isUser: false,
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [inputValue, isLoading, selectedLang]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleClearHistory = useCallback(async () => {
    try {
      await aiService.clearChatHistory();
    } catch {
      // Continue even if backend clear fails
    }
    setMessages([]);
    setError(null);
  }, []);

  const handleQuickAction = (query: string) => {
    handleSendMessage(query);
  };

  return (
    <div className="min-h-[calc(100vh-100px)] p-4 md:p-6 bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-4 gap-6">

        {/* Left Sidebar - Quick Actions */}
        <div className="lg:col-span-1 space-y-4">
          {/* Branding Card */}
          <div className="bg-gradient-to-br from-amber-800 via-amber-900 to-yellow-900 rounded-2xl p-5 text-white shadow-xl border border-amber-700/50">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-amber-700/50 rounded-xl flex items-center justify-center border border-amber-600/50 shadow-inner">
                <Sparkles className="w-6 h-6 text-amber-300" />
              </div>
              <div>
                <h2 className="text-lg font-bold tracking-wide">CocoaFlow</h2>
                <p className="text-amber-300 text-xs font-semibold tracking-widest uppercase">AI Intel</p>
              </div>
            </div>
            <p className="text-amber-200/80 text-sm leading-relaxed">
              Your intelligent factory companion for real-time insights and optimization.
            </p>
          </div>

          {/* Quick Actions Card */}
          <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-4 shadow-lg border border-amber-100">
            <h3 className="text-sm font-bold text-amber-900 mb-3 flex items-center gap-2">
              <Zap className="w-4 h-4 text-amber-600" />
              Quick Actions
            </h3>
            <div className="space-y-2">
              {quickActions.map((action, idx) => (
                <button
                  key={idx}
                  onClick={() => handleQuickAction(action.query)}
                  disabled={isLoading}
                  className="w-full flex items-center gap-3 p-3 rounded-xl bg-amber-50 hover:bg-amber-100 text-amber-900 text-sm font-medium transition-all hover:shadow-md disabled:opacity-50 disabled:cursor-not-allowed border border-transparent hover:border-amber-200"
                >
                  <action.icon className="w-4 h-4 text-amber-700" />
                  {action.label}
                </button>
              ))}
            </div>
          </div>

          {/* Language Selector Card */}
          <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-4 shadow-lg border border-amber-100">
            <h3 className="text-sm font-bold text-amber-900 mb-3">Language</h3>
            <div className="flex flex-wrap gap-2">
              {languages.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => setSelectedLang(lang.code as SupportedLanguage)}
                  className={cn(
                    "px-3 py-1.5 rounded-lg text-xs font-bold transition-all",
                    selectedLang === lang.code
                      ? "bg-amber-800 text-white shadow-md"
                      : "bg-amber-100 text-amber-800 hover:bg-amber-200"
                  )}
                >
                  {lang.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Main Chat Area */}
        <div className="lg:col-span-3">
          <div className="bg-white/90 backdrop-blur-sm rounded-2xl shadow-xl border border-amber-100 overflow-hidden flex flex-col h-[calc(100vh-180px)] min-h-[500px]">

            {/* Chat Header */}
            <div className="bg-gradient-to-r from-amber-800 to-amber-900 text-white px-6 py-4 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-amber-700/50 rounded-xl flex items-center justify-center border border-amber-600/50">
                  <Brain className="w-5 h-5 text-amber-300" />
                </div>
                <div>
                  <h1 className="text-lg font-bold tracking-wide">CocoaFlow AI Intel</h1>
                  <p className="text-amber-300 text-xs font-medium tracking-wider">Global Factory Intelligence</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className={cn(
                  "flex items-center gap-2 rounded-full px-3 py-1.5",
                  isOnline ? "bg-green-500/20" : "bg-amber-700/30"
                )}>
                  {isOnline ? (
                    <Wifi className="w-3 h-3 text-green-400" />
                  ) : (
                    <WifiOff className="w-3 h-3 text-amber-300" />
                  )}
                  <span className={cn(
                    "text-xs font-semibold capitalize",
                    isOnline ? "text-green-300" : "text-amber-200"
                  )}>
                    {provider === 'demo' || provider === 'mock' ? 'Demo Mode' : provider}
                  </span>
                </div>
                <button
                  onClick={handleClearHistory}
                  disabled={isLoading || messages.length === 0}
                  className="p-2 hover:bg-amber-700/50 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  title="Clear Chat"
                >
                  <RefreshCw className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Error Banner */}
            {error && (
              <div className="bg-red-50 border-b border-red-100 px-4 py-2 flex items-center gap-2 text-red-700 text-sm">
                <AlertCircle className="w-4 h-4" />
                <span>{error}</span>
                <button
                  onClick={() => setError(null)}
                  className="ml-auto text-red-500 hover:text-red-700"
                >
                  Dismiss
                </button>
              </div>
            )}

            {/* Chat Messages */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gradient-to-b from-amber-50/50 to-white">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center py-12">
                  <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mb-4">
                    <Bot className="w-10 h-10 text-amber-700" />
                  </div>
                  <h3 className="text-amber-900 font-bold text-lg mb-2">CocoaFlow AI Intel Ready</h3>
                  <p className="text-amber-600 text-sm max-w-md">
                    Ask me about production status, inventory levels, quality control, or get AI-powered recommendations.
                  </p>
                </div>
              )}

              {messages.map((msg) => (
                <div key={msg.id} className={cn("flex w-full", msg.isUser ? "justify-end" : "justify-start")}>
                  {msg.isUser ? (
                    <div className="max-w-[85%] md:max-w-[70%]">
                      <div className="bg-gradient-to-br from-amber-700 to-amber-800 text-white p-4 rounded-2xl rounded-tr-md shadow-lg">
                        <p className="text-[10px] font-bold text-amber-300 mb-1 tracking-widest uppercase">
                          Operator Command
                        </p>
                        <p className="text-base leading-relaxed whitespace-pre-wrap">
                          {msg.content}
                        </p>
                        <p className="text-[10px] text-amber-300/70 mt-2">
                          {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  ) : (
                    <div className="max-w-[90%] md:max-w-[80%]">
                      <div className="bg-white p-5 rounded-2xl rounded-tl-md border border-amber-100 shadow-md relative">
                        <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-amber-600 to-amber-300 rounded-l-2xl"></div>
                        <p className="text-[10px] font-bold text-amber-600 mb-2 tracking-widest uppercase pl-2">
                          CocoaFlow AI Intel
                        </p>
                        <div className="text-gray-800 text-base leading-relaxed whitespace-pre-wrap pl-2">
                          {msg.content}
                        </div>
                        <p className="text-[10px] text-gray-400 mt-3 pl-2">
                          {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {isLoading && (
                <div className="flex justify-start w-full">
                  <div className="bg-white p-4 rounded-2xl rounded-tl-md border border-amber-100 shadow-md flex items-center gap-3">
                    <div className="flex gap-1.5">
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
                    </div>
                    <span className="text-xs font-bold text-amber-700 uppercase tracking-widest">Processing...</span>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 bg-white border-t border-amber-100 shrink-0">
              <div className="flex items-center gap-3">
                <div className="flex-1 relative">
                  <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask CocoaFlow AI Intel..."
                    className="w-full bg-amber-50 border-2 border-transparent focus:border-amber-200 hover:border-amber-100 rounded-xl py-3 pl-4 pr-12 text-gray-700 placeholder:text-gray-400 focus:outline-none transition-all text-base"
                    disabled={isLoading}
                  />
                  <button
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-gray-400 hover:text-amber-700 transition-colors rounded-lg hover:bg-amber-100"
                    title="Voice Input (Coming Soon)"
                  >
                    <Mic className="w-5 h-5" />
                  </button>
                </div>
                <button
                  onClick={() => handleSendMessage()}
                  disabled={!inputValue.trim() || isLoading}
                  className={cn(
                    "p-3 rounded-xl transition-all shadow-md",
                    inputValue.trim() && !isLoading
                      ? "bg-gradient-to-br from-amber-600 to-amber-700 text-white hover:from-amber-700 hover:to-amber-800 active:scale-95"
                      : "bg-gray-200 text-gray-400 cursor-not-allowed"
                  )}
                >
                  <Send className="w-5 h-5" />
                </button>
              </div>

              <div className="flex items-center justify-between mt-3 px-1">
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                    Provider: {provider === 'gemini' ? 'Gemini' : provider === 'anthropic' ? 'Claude' : provider === 'deepseek' ? 'DeepSeek' : 'Demo'}
                  </span>
                  <span className={cn(
                    "w-1.5 h-1.5 rounded-full animate-pulse",
                    isOnline ? "bg-green-500" : "bg-amber-500"
                  )}></span>
                </div>
                <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest">
                  {isOnline ? 'Live Data' : 'Demo Mode'}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIAssistantPage;

import React, { useState } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { Candy, Loader2, AlertCircle } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { toast } from 'sonner';

const LoginPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { useLogin } = useAuth();
  const loginMutation = useLogin();
  
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const from = (location.state as { from?: { pathname?: string } })?.from?.pathname ?? '/dashboard';

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!email || !password) {
      toast.error('Please enter both email and password');
      return;
    }

    try {
      await loginMutation.mutateAsync({ email, password });
      toast.success('Welcome back to CocoaFlow!');
      navigate(from, { replace: true });
    } catch (error: unknown) {
      console.error('Login failed:', error);
      const message = error instanceof Error ? error.message : 'Login failed. Please check your credentials.';
      toast.error(message);
    }
  };

  return (
    <div className="min-h-screen bg-chocolate-50 flex items-center justify-center p-4 relative overflow-hidden">
      {/* Background Decorations */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute -top-20 -right-20 w-96 h-96 bg-primary/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-accent/10 rounded-full blur-3xl"></div>
      </div>

      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden z-10 border border-chocolate-100 animate-in fade-in zoom-in-95 duration-300">
        <div className="p-8">
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary text-primary-foreground mb-4 shadow-lg shadow-primary/20">
              <Candy className="w-8 h-8" />
            </div>
            <h1 className="text-2xl font-bold text-gray-900">Welcome Back</h1>
            <p className="text-gray-500 mt-2 text-sm">
              Sign in to access your chocolate factory dashboard
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {loginMutation.isError && (
              <div className="bg-destructive/10 text-destructive text-sm p-3 rounded-lg flex items-center gap-2">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{loginMutation.error instanceof Error ? loginMutation.error.message : 'Invalid credentials'}</span>
              </div>
            )}

            <div className="space-y-1.5">
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                Email Address
              </label>
              <input
                id="email"
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                placeholder="you@cocoaflow.com"
                disabled={loginMutation.isPending}
              />
            </div>

            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <label htmlFor="password" className="block text-sm font-medium text-gray-700">
                  Password
                </label>
                <a href="#" className="text-xs text-primary hover:underline font-medium">
                  Forgot password?
                </a>
              </div>
              <input
                id="password"
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                disabled={loginMutation.isPending}
              />
            </div>

            <button
              type="submit"
              disabled={loginMutation.isPending}
              className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-semibold py-2.5 rounded-lg shadow-md shadow-primary/20 transition-all active:scale-[0.98] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {loginMutation.isPending ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Signing in...
                </>
              ) : (
                'Sign In'
              )}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-gray-50 text-center">
            <p className="text-sm text-gray-500">
              Don't have an account?{' '}
              <Link to="/register" className="text-primary font-medium hover:underline">
                Create Account
              </Link>
            </p>
          </div>
        </div>
        
        {/* Decorative Bottom Bar */}
        <div className="h-2 w-full bg-gradient-to-r from-primary to-accent"></div>
      </div>
      
      <p className="absolute bottom-6 text-center text-xs text-gray-400">
        ┬⌐ 2026 CocoaFlow AI. All rights reserved.
      </p>
    </div>
  );
};

export default LoginPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Candy, Loader2 } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { toast } from 'sonner';
import { UserRole } from '../../types';

const RegisterPage: React.FC = () => {
  const navigate = useNavigate();
  const { useRegister } = useAuth();
  const registerMutation = useRegister();

  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    role: 'production_worker' as UserRole, // Default role
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.email || !formData.password || !formData.fullName) {
      toast.error('Please fill in all fields');
      return;
    }

    try {
      await registerMutation.mutateAsync(formData);
      toast.success('Account created successfully!');
      navigate('/dashboard');
    } catch (error: unknown) {
      console.error('Registration failed:', error);
      const message = error instanceof Error ? error.message : 'Registration failed. Please try again.';
      toast.error(message);
    }
  };

  return (
    <div className="min-h-screen bg-chocolate-50 flex items-center justify-center p-4 relative overflow-hidden">
      {/* Background Decorations */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-0 right-0 w-80 h-80 bg-primary/5 rounded-full blur-3xl transform translate-x-1/2 -translate-y-1/2"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-accent/5 rounded-full blur-3xl transform -translate-x-1/2 translate-y-1/2"></div>
      </div>

      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden z-10 border border-chocolate-100 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="p-8">
          <div className="text-center mb-6">
            <Link to="/login" className="inline-flex items-center justify-center w-12 h-12 rounded-xl bg-primary/10 text-primary mb-3">
              <Candy className="w-6 h-6" />
            </Link>
            <h1 className="text-2xl font-bold text-gray-900">Create Account</h1>
            <p className="text-gray-500 mt-1 text-sm">
              Join the CocoaFlow team
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-1.5">
              <label htmlFor="fullName" className="block text-sm font-medium text-gray-700">
                Full Name
              </label>
              <input
                id="fullName"
                name="fullName"
                type="text"
                required
                value={formData.fullName}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                placeholder="John Doe"
                disabled={registerMutation.isPending}
              />
            </div>

            <div className="space-y-1.5">
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                Email Address
              </label>
              <input
                id="email"
                name="email"
                type="email"
                required
                value={formData.email}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                placeholder="you@cocoaflow.com"
                disabled={registerMutation.isPending}
              />
            </div>

            <div className="space-y-1.5">
              <label htmlFor="password" className="block text-sm font-medium text-gray-700">
                Password
              </label>
              <input
                id="password"
                name="password"
                type="password"
                required
                value={formData.password}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                placeholder="Create a strong password"
                disabled={registerMutation.isPending}
              />
            </div>

             <div className="space-y-1.5">
              <label htmlFor="role" className="block text-sm font-medium text-gray-700">
                Role (Demo Only)
              </label>
              <select
                id="role"
                name="role"
                value={formData.role}
                onChange={handleChange}
                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-primary/20 focus:border-primary transition-colors bg-gray-50/50 hover:bg-white focus:bg-white outline-none text-sm"
                disabled={registerMutation.isPending}
              >
                <option value="production_worker">Production Worker</option>
                <option value="warehouse_worker">Warehouse Worker</option>
                <option value="quality_controller">Quality Controller</option>
                <option value="mechanic">Mechanic</option>
                <option value="manager">Manager</option>
                <option value="admin">Admin</option>
              </select>
              <p className="text-xs text-gray-400">In production, roles are assigned by admin.</p>
            </div>

            <button
              type="submit"
              disabled={registerMutation.isPending}
              className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-semibold py-2.5 rounded-lg shadow-md shadow-primary/20 transition-all active:scale-[0.98] flex items-center justify-center gap-2 mt-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {registerMutation.isPending ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Creating Account...
                </>
              ) : (
                'Create Account'
              )}
            </button>
          </form>

          <div className="mt-6 pt-6 border-t border-gray-50 text-center">
            <p className="text-sm text-gray-500">
              Already have an account?{' '}
              <Link to="/login" className="text-primary font-medium hover:underline">
                Sign In
              </Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

