const ManagerDashboard: React.FC = () => {
  const navigate = useNavigate();
  const { useCurrentUser } = useAuth();
  const { data: user } = useCurrentUser();
  const { stats, loading: statsLoading, refetch: refetchStats } = useDashboardStats();
  const { analytics, loading: analyticsLoading, refetch: refetchAnalytics } = useAnalytics();

  const [currentTime, setCurrentTime] = useState(new Date());
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Update time every minute
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  // Auto-refresh every 60 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      refetchStats();
      refetchAnalytics();
    }, 60000);
    return () => clearInterval(interval);
  }, [refetchStats, refetchAnalytics]);

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await Promise.all([refetchStats(), refetchAnalytics()]);
    setTimeout(() => setIsRefreshing(false), 500);
  };

  // Format current date/time
  const formattedDate = currentTime.toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
  const formattedTime = currentTime.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
  });

  // Calculate QC approval rate color
  const getQCRateColor = (rate: number): 'success' | 'warning' | 'danger' => {
    if (rate >= 90) return 'success';
    if (rate >= 80) return 'warning';
    return 'danger';
  };

  // Mock data for demonstration (will be replaced by real API data)
  const dashboardMetrics = {
    totalInventoryItems: stats?.totalItems ?? 156,
    inventoryTrend: 5.2,
    lowStockItems: stats?.lowStockItems ?? 8,
    activeBatches: stats?.activeBatches ?? 12,
    batchBreakdown: { mixing: 3, cooking: 4, cooling: 2, packaging: 3 },
    completedToday: stats?.todayProduction ?? 24,
    qcApprovalRate: analytics?.qcApprovalRate ?? 92.5,
    qcTrend: 2.1,
    openAlerts: stats?.openAlerts ?? 2,
    pendingTasks: stats?.pendingTasks ?? 7,
    revenueToday: stats?.todayRevenue ?? 12450,
  };

  // Mock activity data (will be replaced by real API data)
  const recentActivities = analytics?.recentActivities ?? [
    {
      id: '1',
      type: 'batch_started',
      description: 'John started batch #MB-2025-0042',
      user: 'John Smith',
      timestamp: new Date(Date.now() - 5 * 60000).toISOString(),
    },
    {
      id: '2',
      type: 'qc_completed',
      description: 'QC check completed for batch #MB-2025-0041',
      user: 'Sarah Johnson',
      timestamp: new Date(Date.now() - 15 * 60000).toISOString(),
    },
    {
      id: '3',
      type: 'stock_updated',
      description: 'Cocoa powder stock updated (+50kg)',
      user: 'Mike Wilson',
      timestamp: new Date(Date.now() - 30 * 60000).toISOString(),
    },
    {
      id: '4',
      type: 'sos_alert',
      description: 'SOS Alert: Tempering machine #TEMP-002 malfunction',
      user: 'System',
      timestamp: new Date(Date.now() - 45 * 60000).toISOString(),
    },
    {
      id: '5',
      type: 'batch_completed',
      description: 'Batch #MB-2025-0040 completed successfully',
      user: 'Emma Davis',
      timestamp: new Date(Date.now() - 60 * 60000).toISOString(),
    },
    {
      id: '6',
      type: 'task_completed',
      description: 'Equipment inspection task completed',
      user: 'Robert Brown',
      timestamp: new Date(Date.now() - 90 * 60000).toISOString(),
    },
    {
      id: '7',
      type: 'announcement',
      description: 'New safety guidelines posted',
      user: 'Admin',
      timestamp: new Date(Date.now() - 120 * 60000).toISOString(),
    },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <PageHeader
          title="Manager Command Center"
          subtitle={`${formattedDate} ΓÇó ${formattedTime}`}
          icon={LayoutDashboard}
        />
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            size="sm"
            onClick={handleRefresh}
            disabled={isRefreshing}
            className="gap-2"
          >
            <RefreshCw className={cn("w-4 h-4", isRefreshing && "animate-spin")} />
            Refresh
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="gap-2"
          >
            <Download className="w-4 h-4" />
            Export Report
          </Button>
        </div>
      </div>

      {/* Key Metrics Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricsCard
          title="Total Inventory Items"
          value={dashboardMetrics.totalInventoryItems}
          icon={Package}
          trend="up"
          trendValue={dashboardMetrics.inventoryTrend}
          color="default"
          subtitle="Across all categories"
          onClick={() => navigate('/inventory')}
          loading={statsLoading}
        />
        <MetricsCard
          title="Low Stock Items"
          value={dashboardMetrics.lowStockItems}
          icon={AlertTriangle}
          color={dashboardMetrics.lowStockItems > 10 ? 'danger' : dashboardMetrics.lowStockItems > 5 ? 'warning' : 'success'}
          subtitle="Require reorder"
          onClick={() => navigate('/inventory?filter=low-stock')}
          loading={statsLoading}
        />
        <MetricsCard
          title="Active Batches"
          value={dashboardMetrics.activeBatches}
          icon={Factory}
          color="default"
          subtitle={`Mixing: ${dashboardMetrics.batchBreakdown.mixing} | Cooking: ${dashboardMetrics.batchBreakdown.cooking}`}
          onClick={() => navigate('/batches?status=active')}
          loading={statsLoading}
        />
        <MetricsCard
          title="Completed Today"
          value={dashboardMetrics.completedToday}
          icon={CheckCircle2}
          color="success"
          trend="up"
          trendValue={12}
          subtitle="Production batches"
          onClick={() => navigate('/batches?status=completed&date=today')}
          loading={statsLoading}
        />
        <MetricsCard
          title="QC Approval Rate"
          value={dashboardMetrics.qcApprovalRate}
          icon={BarChart3}
          suffix="%"
          trend={dashboardMetrics.qcTrend > 0 ? 'up' : 'down'}
          trendValue={Math.abs(dashboardMetrics.qcTrend)}
          color={getQCRateColor(dashboardMetrics.qcApprovalRate)}
          subtitle="Last 30 days"
          onClick={() => navigate('/qc')}
          loading={analyticsLoading}
        />
        <MetricsCard
          title="Open SOS Alerts"
          value={dashboardMetrics.openAlerts}
          icon={AlertTriangle}
          color={dashboardMetrics.openAlerts > 0 ? 'danger' : 'success'}
          subtitle={dashboardMetrics.openAlerts > 0 ? 'Require attention' : 'All clear'}
          onClick={() => navigate('/mechanic/alerts')}
          loading={statsLoading}
        />
        <MetricsCard
          title="Pending Tasks"
          value={dashboardMetrics.pendingTasks}
          icon={ListTodo}
          color={dashboardMetrics.pendingTasks > 5 ? 'warning' : 'default'}
          subtitle="Assigned to team"
          onClick={() => navigate('/manager/tasks')}
          loading={statsLoading}
        />
        <MetricsCard
          title="Revenue Today"
          value={dashboardMetrics.revenueToday}
          icon={DollarSign}
          prefix="$"
          color="success"
          trend="up"
          trendValue={8.5}
          subtitle="From completed orders"
          loading={statsLoading}
        />
      </div>

      {/* Main Content - Charts & Activity */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Charts Section - 2 columns */}
        <div className="xl:col-span-2">
          <ChartsSection
            analytics={analytics}
            loading={analyticsLoading}
          />
        </div>

        {/* Activity Timeline - 1 column */}
        <div className="xl:col-span-1">
          <Card className="h-full">
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="flex items-center gap-2 text-lg">
                <Clock className="w-5 h-5 text-cocoa-600" />
                Recent Activity
              </CardTitle>
              <Badge variant="secondary" className="text-xs">
                Live
              </Badge>
            </CardHeader>
            <CardContent>
              <ActivityTimeline
                activities={recentActivities}
                loading={statsLoading}
              />
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Department Cards */}
      <div>
        <h2 className="text-lg font-semibold text-cocoa-900 mb-4 flex items-center gap-2">
          <Users className="w-5 h-5" />
          Department Overview
        </h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
          {departments.map((dept) => {
            const Icon = dept.icon;
            return (
              <button
                key={dept.id}
                onClick={() => navigate(dept.href)}
                className={cn(
                  "p-4 rounded-xl border-2 transition-all duration-200 text-left group",
                  dept.bgColor,
                  dept.borderColor,
                  "hover:shadow-md hover:scale-[1.02]"
                )}
              >
                <div className={cn(
                  "w-10 h-10 rounded-lg flex items-center justify-center mb-3 transition-transform group-hover:scale-110",
                  dept.color
                )}>
                  <Icon className="w-5 h-5 text-white" />
                </div>
                <h3 className="font-semibold text-cocoa-900 mb-1">
                  {dept.title}
                </h3>
                <p className="text-xs text-slate-500 line-clamp-2">
                  {dept.description}
                </p>
              </button>
            );
          })}
        </div>
      </div>

      {/* Quick Stats Footer */}
      <Card className="bg-gradient-to-r from-cocoa-50 to-chocolate-50 border-cocoa-200">
        <CardContent className="py-4">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div className="flex items-center gap-6">
              <div className="text-sm">
                <span className="text-slate-500">Last updated:</span>
                <span className="ml-2 font-medium text-cocoa-700">
                  {formattedTime}
                </span>
              </div>
              <div className="h-4 w-px bg-slate-300" />
              <div className="text-sm">
                <span className="text-slate-500">Auto-refresh:</span>
                <span className="ml-2 font-medium text-green-600">Every 60s</span>
              </div>
            </div>
            <div className="flex items-center gap-4 text-sm">
              <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                <span className="text-slate-600">System Online</span>
              </div>
              <div className="flex items-center gap-1.5">
                <TrendingUp className="w-4 h-4 text-green-500" />
                <span className="text-green-600 font-medium">+15% productivity</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default ManagerDashboard;

import React, { useState, useMemo } from 'react';
import {
  ListTodo,
  Plus,
  Search,
  Edit2,
  Trash2,
  Calendar,
  User,
  Clock,
  LayoutGrid,
  List,
  AlertCircle,
  CheckCircle2,
  Circle,
  XCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { Input } from '../../components/ui/Input';
import { Modal } from '../../components/common/Modal';
import TaskModal from '../../components/manager/TaskModal';
import { useTasks } from '../../hooks/useTasks';
import { useDeleteTask } from '../../hooks/useTaskMutations';
import { useUsers } from '../../hooks/useUsers';
import { Task, TaskStatus, TaskPriority, User as UserType } from '../../types';
import { cn } from '../../lib/utils';

// Status configuration
const statusConfig: Record<TaskStatus, {
  label: string;
  icon: typeof Circle;
  color: string;
  bgColor: string;
  borderColor: string;
}> = {
  pending: {
    label: 'Pending',
    icon: Circle,
    color: 'text-slate-600',
    bgColor: 'bg-slate-100',
    borderColor: 'border-slate-300',
  },
  in_progress: {
    label: 'In Progress',
    icon: Clock,
    color: 'text-blue-600',
    bgColor: 'bg-blue-100',
    borderColor: 'border-blue-300',
  },
  completed: {
    label: 'Completed',
    icon: CheckCircle2,
    color: 'text-green-600',
    bgColor: 'bg-green-100',
    borderColor: 'border-green-300',
  },
  cancelled: {
    label: 'Cancelled',
    icon: XCircle,
    color: 'text-red-600',
    bgColor: 'bg-red-100',
    borderColor: 'border-red-300',
  },
};

// Priority configuration
const priorityConfig: Record<TaskPriority, { label: string; variant: 'error' | 'warning' | 'default' | 'secondary' }> = {
  urgent: { label: 'Urgent', variant: 'error' },
  high: { label: 'High', variant: 'warning' },
  medium: { label: 'Medium', variant: 'default' },
  low: { label: 'Low', variant: 'secondary' },
};

const TasksPage: React.FC = () => {
  // State
  const [viewMode, setViewMode] = useState<'board' | 'table'>('board');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<TaskStatus | 'all'>('all');
  const [priorityFilter, setPriorityFilter] = useState<TaskPriority | 'all'>('all');
  const [assigneeFilter, setAssigneeFilter] = useState<string>('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [taskToDelete, setTaskToDelete] = useState<Task | null>(null);

  // Hooks
  const { tasks = [], loading, refetch } = useTasks();
  const { users = [] } = useUsers();
  const deleteTaskMutation = useDeleteTask();

  // Filter tasks
  const filteredTasks = useMemo(() => {
    return tasks.filter((task: Task) => {
      const matchesSearch =
        searchQuery === '' ||
        task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.description?.toLowerCase().includes(searchQuery.toLowerCase());

      const matchesStatus =
        statusFilter === 'all' || task.status === statusFilter;

      const matchesPriority =
        priorityFilter === 'all' || task.priority === priorityFilter;

      const matchesAssignee =
        assigneeFilter === 'all' || task.assigned_to === assigneeFilter;

      return matchesSearch && matchesStatus && matchesPriority && matchesAssignee;
    });
  }, [tasks, searchQuery, statusFilter, priorityFilter, assigneeFilter]);

  // Group tasks by status for Kanban board
  const tasksByStatus = useMemo(() => {
    const grouped: Record<TaskStatus, Task[]> = {
      pending: [],
      in_progress: [],
      completed: [],
      cancelled: [],
    };

    filteredTasks.forEach((task: Task) => {
      if (grouped[task.status]) {
        grouped[task.status].push(task);
      }
    });

    return grouped;
  }, [filteredTasks]);

  // Handlers
  const handleCreateNew = () => {
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEdit = (task: Task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleDelete = (task: Task) => {
    setTaskToDelete(task);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!taskToDelete) return;

    try {
      await deleteTaskMutation.mutateAsync(taskToDelete.id);
      toast.success('Task deleted successfully');
      setIsDeleteModalOpen(false);
      setTaskToDelete(null);
      refetch();
    } catch (error) {
      toast.error('Failed to delete task');
    }
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setSelectedTask(null);
    refetch();
  };

  // Helper functions
  const formatDate = (dateString?: string) => {
    if (!dateString) return 'No due date';
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  const isOverdue = (task: Task) => {
    if (!task.due_date || task.status === 'completed' || task.status === 'cancelled') return false;
    return new Date(task.due_date) < new Date();
  };

  const isDueSoon = (task: Task) => {
    if (!task.due_date || task.status === 'completed' || task.status === 'cancelled') return false;
    const dueDate = new Date(task.due_date);
    const now = new Date();
    const twoDaysFromNow = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000);
    return dueDate <= twoDaysFromNow && dueDate > now;
  };

  // Task Card Component
  const TaskCard: React.FC<{ task: Task; showActions?: boolean }> = ({ task, showActions = true }) => {
    const config = statusConfig[task.status];
    const priorityConf = priorityConfig[task.priority];

    return (
      <div
        className={cn(
          "p-4 bg-white rounded-lg border-2 transition-all hover:shadow-md cursor-pointer group",
          config.borderColor,
          isOverdue(task) && "border-red-400 bg-red-50/50"
        )}
        onClick={() => handleEdit(task)}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-2 mb-2">
          <h4 className="font-medium text-cocoa-900 line-clamp-2 flex-1">
            {task.title}
          </h4>
          <Badge variant={priorityConf.variant} className="flex-shrink-0 text-xs">
            {priorityConf.label}
          </Badge>
        </div>

        {/* Description */}
        {task.description && (
          <p className="text-sm text-slate-500 line-clamp-2 mb-3">
            {task.description}
          </p>
        )}

        {/* Meta info */}
        <div className="space-y-2 text-xs">
          {/* Assignee */}
          <div className="flex items-center gap-2 text-slate-500">
            <User className="w-3.5 h-3.5" />
            <span>{task.assigned_to_name || 'Unassigned'}</span>
          </div>

          {/* Due date */}
          <div className={cn(
            "flex items-center gap-2",
            isOverdue(task) ? "text-red-600" : isDueSoon(task) ? "text-amber-600" : "text-slate-500"
          )}>
            <Calendar className="w-3.5 h-3.5" />
            <span className={cn(isOverdue(task) && "font-medium")}>
              {isOverdue(task) && 'Overdue: '}
              {formatDate(task.due_date)}
            </span>
          </div>
        </div>

        {/* Actions */}
        {showActions && (
          <div className="flex items-center gap-2 mt-3 pt-3 border-t border-slate-100 opacity-0 group-hover:opacity-100 transition-opacity">
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                handleEdit(task);
              }}
              className="flex-1"
            >
              <Edit2 className="w-3 h-3 mr-1" />
              Edit
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                handleDelete(task);
              }}
              className="flex-1 text-red-500 hover:text-red-700 hover:bg-red-50"
            >
              <Trash2 className="w-3 h-3 mr-1" />
              Delete
            </Button>
          </div>
        )}
      </div>
    );
  };

  // Kanban Column Component
  const KanbanColumn: React.FC<{ status: TaskStatus; tasks: Task[] }> = ({ status, tasks }) => {
    const config = statusConfig[status];
    const StatusIcon = config.icon;

    return (
      <div className={cn(
        "flex-1 min-w-[280px] rounded-xl p-4",
        config.bgColor
      )}>
        {/* Column header */}
        <div className="flex items-center gap-2 mb-4">
          <StatusIcon className={cn("w-5 h-5", config.color)} />
          <h3 className={cn("font-semibold", config.color)}>
            {config.label}
          </h3>
          <Badge variant="secondary" className="ml-auto">
            {tasks.length}
          </Badge>
        </div>

        {/* Tasks */}
        <div className="space-y-3 max-h-[calc(100vh-350px)] overflow-y-auto">
          {tasks.length === 0 ? (
            <div className="text-center py-8 text-slate-400">
              <p className="text-sm">No tasks</p>
            </div>
          ) : (
            tasks.map((task) => (
              <TaskCard key={task.id} task={task} />
            ))
          )}
        </div>

        {/* Status change hint */}
        {status !== 'completed' && status !== 'cancelled' && (
          <div className="mt-4 pt-3 border-t border-slate-200/50">
            <p className="text-xs text-slate-400 text-center">
              Click a task to change status
            </p>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <PageHeader
          title="Task Management"
          subtitle="Assign and track tasks for your team"
          icon={ListTodo}
        />
        <div className="flex items-center gap-3">
          {/* View toggle */}
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <Button
              variant={viewMode === 'board' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('board')}
              className="gap-1"
            >
              <LayoutGrid className="w-4 h-4" />
              Board
            </Button>
            <Button
              variant={viewMode === 'table' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('table')}
              className="gap-1"
            >
              <List className="w-4 h-4" />
              Table
            </Button>
          </div>
          <Button onClick={handleCreateNew} className="gap-2">
            <Plus className="w-4 h-4" />
            Create Task
          </Button>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="py-4">
          <div className="flex flex-col lg:flex-row gap-4">
            {/* Search */}
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <Input
                placeholder="Search tasks..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as TaskStatus | 'all')}
              className="px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-cocoa-500"
            >
              <option value="all">All Status</option>
              <option value="pending">Pending</option>
              <option value="in_progress">In Progress</option>
              <option value="completed">Completed</option>
              <option value="cancelled">Cancelled</option>
            </select>

            {/* Priority Filter */}
            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value as TaskPriority | 'all')}
              className="px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-cocoa-500"
            >
              <option value="all">All Priorities</option>
              <option value="urgent">Urgent</option>
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>

            {/* Assignee Filter */}
            <select
              value={assigneeFilter}
              onChange={(e) => setAssigneeFilter(e.target.value)}
              className="px-3 py-2 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-cocoa-500"
            >
              <option value="all">All Assignees</option>
              {users.map((user: UserType) => (
                <option key={user.id} value={user.id}>
                  {user.full_name}
                </option>
              ))}
            </select>
          </div>
        </CardContent>
      </Card>

      {/* Content */}
      {loading ? (
        // Loading skeleton
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="bg-slate-100 rounded-xl p-4 animate-pulse">
              <div className="h-6 bg-slate-200 rounded w-24 mb-4" />
              <div className="space-y-3">
                {[...Array(2)].map((_, j) => (
                  <div key={j} className="h-32 bg-slate-200 rounded" />
                ))}
              </div>
            </div>
          ))}
        </div>
      ) : viewMode === 'board' ? (
        // Kanban Board View
        <div className="flex gap-4 overflow-x-auto pb-4">
          {(['pending', 'in_progress', 'completed', 'cancelled'] as TaskStatus[]).map((status) => (
            <KanbanColumn
              key={status}
              status={status}
              tasks={tasksByStatus[status]}
            />
          ))}
        </div>
      ) : (
        // Table View
        <Card>
          <CardContent className="p-0">
            {filteredTasks.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <ListTodo className="w-8 h-8 text-slate-400" />
                </div>
                <h3 className="text-lg font-medium text-slate-700 mb-2">
                  No tasks found
                </h3>
                <p className="text-slate-500 mb-4">
                  {searchQuery || statusFilter !== 'all' || priorityFilter !== 'all'
                    ? 'Try adjusting your filters'
                    : 'Create your first task to get started'}
                </p>
                <Button onClick={handleCreateNew} className="gap-2">
                  <Plus className="w-4 h-4" />
                  Create Task
                </Button>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-slate-50 border-b">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Task
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Assignee
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Priority
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Status
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Due Date
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-semibold text-slate-600 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {filteredTasks.map((task: Task) => {
                      const config = statusConfig[task.status];
                      const priorityConf = priorityConfig[task.priority];
                      const StatusIcon = config.icon;

                      return (
                        <tr
                          key={task.id}
                          className={cn(
                            "hover:bg-slate-50 transition-colors cursor-pointer",
                            isOverdue(task) && "bg-red-50/50"
                          )}
                          onClick={() => handleEdit(task)}
                        >
                          <td className="px-4 py-3">
                            <div>
                              <p className="font-medium text-cocoa-900">
                                {task.title}
                              </p>
                              {task.description && (
                                <p className="text-sm text-slate-500 line-clamp-1">
                                  {task.description}
                                </p>
                              )}
                            </div>
                          </td>
                          <td className="px-4 py-3">
                            <div className="flex items-center gap-2">
                              <div className="w-7 h-7 bg-cocoa-100 rounded-full flex items-center justify-center text-cocoa-600 font-medium text-xs">
                                {task.assigned_to_name?.charAt(0) || '?'}
                              </div>
                              <span className="text-sm text-slate-600">
                                {task.assigned_to_name || 'Unassigned'}
                              </span>
                            </div>
                          </td>
                          <td className="px-4 py-3">
                            <Badge variant={priorityConf.variant}>
                              {priorityConf.label}
                            </Badge>
                          </td>
                          <td className="px-4 py-3">
                            <div className={cn(
                              "inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-xs font-medium",
                              config.bgColor,
                              config.color
                            )}>
                              <StatusIcon className="w-3 h-3" />
                              {config.label}
                            </div>
                          </td>
                          <td className="px-4 py-3">
                            <span className={cn(
                              "text-sm",
                              isOverdue(task) ? "text-red-600 font-medium" : isDueSoon(task) ? "text-amber-600" : "text-slate-600"
                            )}>
                              {isOverdue(task) && (
                                <AlertCircle className="w-4 h-4 inline mr-1" />
                              )}
                              {formatDate(task.due_date)}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-right">
                            <div className="flex items-center justify-end gap-1">
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleEdit(task);
                                }}
                              >
                                <Edit2 className="w-4 h-4" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleDelete(task);
                                }}
                                className="text-red-500 hover:text-red-700 hover:bg-red-50"
                              >
                                <Trash2 className="w-4 h-4" />
                              </Button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Stats summary */}
      {!loading && tasks.length > 0 && (
        <div className="flex flex-wrap items-center gap-6 text-sm text-slate-500 px-1">
          <span>
            Showing {filteredTasks.length} of {tasks.length} tasks
          </span>
          <span className="flex items-center gap-1">
            <Circle className="w-3 h-3 text-slate-400" />
            Pending: {tasksByStatus.pending.length}
          </span>
          <span className="flex items-center gap-1">
            <Clock className="w-3 h-3 text-blue-500" />
            In Progress: {tasksByStatus.in_progress.length}
          </span>
          <span className="flex items-center gap-1">
            <CheckCircle2 className="w-3 h-3 text-green-500" />
            Completed: {tasksByStatus.completed.length}
          </span>
          <span className="flex items-center gap-1 text-red-500">
            <AlertCircle className="w-3 h-3" />
            Overdue: {filteredTasks.filter(isOverdue).length}
          </span>
        </div>
      )}

      {/* Create/Edit Modal */}
      <TaskModal
        isOpen={isModalOpen}
        onClose={handleModalClose}
        task={selectedTask}
        onSuccess={handleModalClose}
      />

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Task"
      >
        <div className="p-4">
          <p className="text-slate-600 mb-4">
            Are you sure you want to delete "{taskToDelete?.title}"? This action cannot be undone.
          </p>
          <div className="flex justify-end gap-3">
            <Button
              variant="outline"
              onClick={() => setIsDeleteModalOpen(false)}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={confirmDelete}
              disabled={deleteTaskMutation.isPending}
            >
              {deleteTaskMutation.isPending ? 'Deleting...' : 'Delete'}
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default TasksPage;

import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  Wrench,
  AlertTriangle,
  Calendar,
  MapPin,
  Settings,
  Clock,
  FileText,
  History,
  Bell,
  DollarSign,
} from 'lucide-react';
import PageHeader, { PageHeaderCompact } from '../../components/layout/PageHeader';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import MaintenanceLogModal from '../../components/mechanic/MaintenanceLogModal';
import SOSAlertCard from '../../components/mechanic/SOSAlertCard';
import ResolveAlertModal from '../../components/mechanic/ResolveAlertModal';
import { useMechanic } from '../../hooks/useMechanic';
import { Machine, MachineStatus, MaintenanceLog, SOSAlert } from '../../types';

type TabType = 'overview' | 'maintenance' | 'alerts';

const MachineDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { useMachine, useMaintenanceLogs, useSOSAlerts, useCreateSOSAlert } = useMechanic();

  const { data: machine, isLoading: machineLoading } = useMachine(id || '');
  const { data: maintenanceLogs = [] } = useMaintenanceLogs({ machineId: id });
  const { data: machineAlerts = [] } = useSOSAlerts({ machineId: id });

  // State
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [isMaintenanceModalOpen, setIsMaintenanceModalOpen] = useState(false);
  const [selectedAlert, setSelectedAlert] = useState<SOSAlert | null>(null);
  const [isResolveModalOpen, setIsResolveModalOpen] = useState(false);
  const [isCreatingSOS, setIsCreatingSOS] = useState(false);

  const createSOSMutation = useCreateSOSAlert();

  const getStatusConfig = (status: MachineStatus) => {
    switch (status) {
      case 'operational':
        return { color: 'bg-green-500', bgColor: 'bg-green-50 border-green-200', textColor: 'text-green-700', variant: 'success' as const };
      case 'maintenance':
        return { color: 'bg-amber-500', bgColor: 'bg-amber-50 border-amber-200', textColor: 'text-amber-700', variant: 'warning' as const };
      case 'repair':
        return { color: 'bg-red-500', bgColor: 'bg-red-50 border-red-200', textColor: 'text-red-700', variant: 'error' as const };
      case 'offline':
        return { color: 'bg-gray-500', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-700', variant: 'default' as const };
      case 'standby':
        return { color: 'bg-blue-500', bgColor: 'bg-blue-50 border-blue-200', textColor: 'text-blue-700', variant: 'default' as const };
      default:
        return { color: 'bg-gray-400', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-600', variant: 'default' as const };
    }
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString();
  };

  const tabs = [
    { id: 'overview' as TabType, label: 'Overview', icon: Settings },
    { id: 'maintenance' as TabType, label: 'Maintenance History', icon: History },
    { id: 'alerts' as TabType, label: 'SOS History', icon: Bell },
  ];

  if (machineLoading) {
    return (
      <div className="space-y-6">
        <div className="h-8 w-48 bg-gray-200 rounded animate-pulse" />
        <div className="h-64 bg-gray-100 rounded-xl animate-pulse" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-32 bg-gray-100 rounded-xl animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  if (!machine) {
    return (
      <div className="text-center py-12">
        <Settings className="w-16 h-16 text-gray-300 mx-auto mb-4" />
        <h2 className="text-xl font-semibold text-gray-700 mb-2">Machine Not Found</h2>
        <p className="text-gray-500 mb-4">The machine you're looking for doesn't exist.</p>
        <Button variant="outline" onClick={() => navigate('/mechanic/machines')}>
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Machines
        </Button>
      </div>
    );
  }

  const statusConfig = getStatusConfig(machine.status);
  const openAlerts = machineAlerts.filter((a: SOSAlert) => a.status === 'open' || a.status === 'in_progress');

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeaderCompact
        title={machine.name}
        backLink="/mechanic/machines"
        backLabel="Back to Machines"
        actions={
          <div className="flex gap-2">
            <Button
              variant="destructive"
              onClick={() => setIsCreatingSOS(true)}
              disabled={machine.status === 'repair'}
            >
              <AlertTriangle className="w-4 h-4 mr-2" />
              Create SOS Alert
            </Button>
            <Button variant="default" onClick={() => setIsMaintenanceModalOpen(true)}>
              <Wrench className="w-4 h-4 mr-2" />
              Log Maintenance
            </Button>
          </div>
        }
      />

      {/* Machine Header Card */}
      <Card className={`border-2 ${statusConfig.bgColor}`}>
        <CardContent className="p-6">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className={`w-16 h-16 rounded-xl ${statusConfig.color} flex items-center justify-center ${machine.status === 'repair' ? 'animate-pulse' : ''}`}>
                <Settings className="w-8 h-8 text-white" />
              </div>
              <div>
                <div className="flex items-center gap-3 mb-1">
                  <h1 className="text-2xl font-bold text-chocolate-800">{machine.name}</h1>
                  <Badge variant={statusConfig.variant} className="text-sm">
                    {machine.status}
                  </Badge>
                </div>
                <p className="text-gray-600">{machine.type}</p>
                <p className="text-sm font-mono text-gray-500">{machine.machine_code}</p>
              </div>
            </div>
            <div className="flex items-center gap-2 text-gray-600">
              <MapPin className="w-5 h-5" />
              <span className="text-lg">{machine.location}</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Open Alerts Warning */}
      {openAlerts.length > 0 && (
        <div className="bg-red-50 border-2 border-red-200 rounded-xl p-4">
          <div className="flex items-center gap-3 mb-3">
            <AlertTriangle className="w-6 h-6 text-red-600" />
            <h3 className="font-bold text-red-800">
              {openAlerts.length} Active Alert{openAlerts.length > 1 ? 's' : ''}
            </h3>
          </div>
          <div className="space-y-2">
            {openAlerts.slice(0, 2).map((alert: SOSAlert) => (
              <SOSAlertCard
                key={alert.id}
                alert={alert}
                onRespond={() => {
                  setSelectedAlert(alert);
                  setIsResolveModalOpen(true);
                }}
                compact
              />
            ))}
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <div className="flex gap-1">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-3 border-b-2 transition-colors ${
                  activeTab === tab.id
                    ? 'border-chocolate-600 text-chocolate-700 bg-chocolate-50'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                <Icon className="w-4 h-4" />
                <span className="font-medium">{tab.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Machine Info */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <FileText className="w-5 h-5 text-chocolate-600" />
                Machine Information
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex justify-between">
                <span className="text-gray-600">Type</span>
                <span className="font-medium">{machine.type}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Code</span>
                <span className="font-mono">{machine.machine_code}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Location</span>
                <span className="font-medium">{machine.location}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Status</span>
                <Badge variant={statusConfig.variant}>{machine.status}</Badge>
              </div>
            </CardContent>
          </Card>

          {/* Maintenance Info */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Calendar className="w-5 h-5 text-chocolate-600" />
                Maintenance Schedule
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex justify-between">
                <span className="text-gray-600">Last Maintenance</span>
                <span className="font-medium">{formatDate(machine.last_maintenance_date)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Next Scheduled</span>
                <span className={`font-medium ${machine.next_maintenance_date && new Date(machine.next_maintenance_date) <= new Date() ? 'text-red-600' : ''}`}>
                  {formatDate(machine.next_maintenance_date)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Total Logs</span>
                <span className="font-medium">{maintenanceLogs.length}</span>
              </div>
            </CardContent>
          </Card>

          {/* Stats */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Clock className="w-5 h-5 text-chocolate-600" />
                Statistics
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex justify-between">
                <span className="text-gray-600">Total Maintenance</span>
                <span className="font-medium">{maintenanceLogs.length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Total SOS Alerts</span>
                <span className="font-medium">{machineAlerts.length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Open Alerts</span>
                <span className={`font-medium ${openAlerts.length > 0 ? 'text-red-600' : 'text-green-600'}`}>
                  {openAlerts.length}
                </span>
              </div>
            </CardContent>
          </Card>

          {/* Notes */}
          {machine.notes && (
            <Card className="md:col-span-2 lg:col-span-3">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <FileText className="w-5 h-5 text-chocolate-600" />
                  Notes
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-gray-700 whitespace-pre-wrap">{machine.notes}</p>
              </CardContent>
            </Card>
          )}
        </div>
      )}

      {activeTab === 'maintenance' && (
        <div className="space-y-4">
          {maintenanceLogs.length === 0 ? (
            <Card className="py-12">
              <CardContent className="text-center">
                <History className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-gray-700 mb-2">
                  No Maintenance History
                </h3>
                <p className="text-gray-500 mb-4">
                  No maintenance has been logged for this machine yet.
                </p>
                <Button variant="default" onClick={() => setIsMaintenanceModalOpen(true)}>
                  <Wrench className="w-4 h-4 mr-2" />
                  Log Maintenance
                </Button>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {maintenanceLogs.map((log: MaintenanceLog) => (
                <Card key={log.id} className="hover:shadow-md transition-shadow">
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <Badge
                          variant={
                            log.maintenance_type === 'emergency'
                              ? 'error'
                              : log.maintenance_type === 'corrective'
                              ? 'warning'
                              : 'default'
                          }
                        >
                          {log.maintenance_type}
                        </Badge>
                        <span className="text-sm text-gray-500">
                          {new Date(log.date).toLocaleDateString()}
                        </span>
                      </div>
                      {log.cost && (
                        <span className="flex items-center text-sm text-gray-600">
                          <DollarSign className="w-4 h-4" />
                          {log.cost.toFixed(2)}
                        </span>
                      )}
                    </div>
                    <p className="text-gray-800 mb-2">{log.description}</p>
                    <div className="flex items-center gap-4 text-sm text-gray-500">
                      {log.performed_by_name && (
                        <span>By: {log.performed_by_name}</span>
                      )}
                      {log.duration_minutes && (
                        <span className="flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {log.duration_minutes} min
                        </span>
                      )}
                      {log.parts_replaced && log.parts_replaced.length > 0 && (
                        <span>Parts: {log.parts_replaced.join(', ')}</span>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>
      )}

      {activeTab === 'alerts' && (
        <div className="space-y-4">
          {machineAlerts.length === 0 ? (
            <Card className="py-12">
              <CardContent className="text-center">
                <Bell className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-gray-700 mb-2">
                  No SOS Alert History
                </h3>
                <p className="text-gray-500">
                  No SOS alerts have been reported for this machine.
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {machineAlerts.map((alert: SOSAlert) => (
                <SOSAlertCard
                  key={alert.id}
                  alert={alert}
                  onRespond={() => {
                    setSelectedAlert(alert);
                    setIsResolveModalOpen(true);
                  }}
                />
              ))}
            </div>
          )}
        </div>
      )}

      {/* Modals */}
      <MaintenanceLogModal
        isOpen={isMaintenanceModalOpen}
        onClose={() => setIsMaintenanceModalOpen(false)}
        machineId={id}
      />

      {selectedAlert && (
        <ResolveAlertModal
          isOpen={isResolveModalOpen}
          onClose={() => {
            setIsResolveModalOpen(false);
            setSelectedAlert(null);
          }}
          alert={selectedAlert}
          onResolved={() => {
            setIsResolveModalOpen(false);
            setSelectedAlert(null);
          }}
        />
      )}
    </div>
  );
};

export default MachineDetailPage;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search,
  Filter,
  Plus,
  Wrench,
  AlertTriangle,
  Calendar,
  MapPin,
  Settings,
} from 'lucide-react';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import MaintenanceLogModal from '../../components/mechanic/MaintenanceLogModal';
import { useMechanic } from '../../hooks/useMechanic';
import { Machine, MachineStatus } from '../../types';

const MachinesPage: React.FC = () => {
  const navigate = useNavigate();
  const { useMachines } = useMechanic();
  const { data: machines = [], isLoading } = useMachines();

  // State
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<MachineStatus | 'all'>('all');
  const [isMaintenanceModalOpen, setIsMaintenanceModalOpen] = useState(false);
  const [selectedMachineId, setSelectedMachineId] = useState<string | undefined>();

  // Filter machines
  const filteredMachines = machines.filter((machine: Machine) => {
    // Status filter
    if (statusFilter !== 'all' && machine.status !== statusFilter) return false;

    // Search filter
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        machine.name.toLowerCase().includes(query) ||
        machine.machine_code.toLowerCase().includes(query) ||
        machine.type.toLowerCase().includes(query)
      );
    }
    return true;
  });

  // Sort by next maintenance date (urgent first)
  const sortedMachines = [...filteredMachines].sort((a, b) => {
    // Machines needing repair/maintenance first
    const statusOrder = { repair: 0, maintenance: 1, offline: 2, standby: 3, operational: 4 };
    const statusDiff = statusOrder[a.status] - statusOrder[b.status];
    if (statusDiff !== 0) return statusDiff;

    // Then by next maintenance date
    if (a.next_maintenance_date && b.next_maintenance_date) {
      return new Date(a.next_maintenance_date).getTime() - new Date(b.next_maintenance_date).getTime();
    }
    return 0;
  });

  const getStatusConfig = (status: MachineStatus) => {
    switch (status) {
      case 'operational':
        return { color: 'bg-green-500', bgColor: 'bg-green-50 border-green-200', textColor: 'text-green-700', variant: 'success' as const };
      case 'maintenance':
        return { color: 'bg-amber-500', bgColor: 'bg-amber-50 border-amber-200', textColor: 'text-amber-700', variant: 'warning' as const };
      case 'repair':
        return { color: 'bg-red-500', bgColor: 'bg-red-50 border-red-200', textColor: 'text-red-700', variant: 'error' as const };
      case 'offline':
        return { color: 'bg-gray-500', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-700', variant: 'default' as const };
      case 'standby':
        return { color: 'bg-blue-500', bgColor: 'bg-blue-50 border-blue-200', textColor: 'text-blue-700', variant: 'default' as const };
      default:
        return { color: 'bg-gray-400', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-600', variant: 'default' as const };
    }
  };

  const isMaintenanceDue = (machine: Machine): boolean => {
    if (!machine.next_maintenance_date) return false;
    const nextDate = new Date(machine.next_maintenance_date);
    const now = new Date();
    const oneWeekLater = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    return nextDate <= oneWeekLater;
  };

  const handleLogMaintenance = (machineId: string) => {
    setSelectedMachineId(machineId);
    setIsMaintenanceModalOpen(true);
  };

  const statusOptions: { value: MachineStatus | 'all'; label: string }[] = [
    { value: 'all', label: 'All Statuses' },
    { value: 'operational', label: 'Operational' },
    { value: 'maintenance', label: 'Maintenance' },
    { value: 'repair', label: 'Repair' },
    { value: 'offline', label: 'Offline' },
    { value: 'standby', label: 'Standby' },
  ];

  // Stats
  const operationalCount = machines.filter((m: Machine) => m.status === 'operational').length;
  const maintenanceCount = machines.filter((m: Machine) => m.status === 'maintenance' || m.status === 'repair').length;
  const maintenanceDueCount = machines.filter((m: Machine) => isMaintenanceDue(m)).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader
        title="Machines"
        subtitle="View and manage all factory machines"
        icon={Settings}
      />

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-gray-600 font-medium">Total Machines</p>
                <p className="text-2xl font-bold text-gray-800">{machines.length}</p>
              </div>
              <Settings className="w-8 h-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-green-50 border-green-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-green-600 font-medium">Operational</p>
                <p className="text-2xl font-bold text-green-800">{operationalCount}</p>
              </div>
              <Wrench className="w-8 h-8 text-green-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-amber-600 font-medium">Needs Attention</p>
                <p className="text-2xl font-bold text-amber-800">{maintenanceCount}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-amber-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-blue-50 border-blue-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-blue-600 font-medium">Maintenance Due</p>
                <p className="text-2xl font-bold text-blue-800">{maintenanceDueCount}</p>
              </div>
              <Calendar className="w-8 h-8 text-blue-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            type="text"
            placeholder="Search by name or code..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Status Filter */}
        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-gray-400" />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as MachineStatus | 'all')}
            className="px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500 focus:border-chocolate-500 text-sm"
          >
            {statusOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Machines Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="h-64 bg-gray-100 rounded-xl animate-pulse" />
          ))}
        </div>
      ) : sortedMachines.length === 0 ? (
        <Card className="py-12">
          <CardContent className="text-center">
            <Settings className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-700 mb-2">
              No machines found
            </h3>
            <p className="text-gray-500">
              {searchQuery || statusFilter !== 'all'
                ? 'No machines match your search criteria.'
                : 'No machines have been registered yet.'}
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {sortedMachines.map((machine: Machine) => {
            const config = getStatusConfig(machine.status);
            const maintenanceDue = isMaintenanceDue(machine);

            return (
              <Card
                key={machine.id}
                className={`border-2 hover:shadow-lg transition-all cursor-pointer ${config.bgColor}`}
                onClick={() => navigate(`/mechanic/machines/${machine.id}`)}
              >
                <CardContent className="p-6">
                  {/* Header */}
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className={`w-4 h-4 rounded-full ${config.color} ${machine.status === 'repair' ? 'animate-pulse' : ''}`} />
                      <Badge variant={config.variant}>{machine.status}</Badge>
                    </div>
                    <span className="text-xs font-mono text-gray-500">
                      {machine.machine_code}
                    </span>
                  </div>

                  {/* Machine Info */}
                  <h3 className="font-bold text-lg text-chocolate-800 mb-1">
                    {machine.name}
                  </h3>
                  <p className="text-sm text-gray-600 mb-3">{machine.type}</p>

                  {/* Location */}
                  <div className="flex items-center gap-2 text-sm text-gray-500 mb-4">
                    <MapPin className="w-4 h-4" />
                    <span>{machine.location}</span>
                  </div>

                  {/* Maintenance Info */}
                  <div className="space-y-2 text-sm">
                    {machine.last_maintenance_date && (
                      <div className="flex items-center justify-between text-gray-600">
                        <span>Last Maintenance:</span>
                        <span>{new Date(machine.last_maintenance_date).toLocaleDateString()}</span>
                      </div>
                    )}
                    {machine.next_maintenance_date && (
                      <div className={`flex items-center justify-between ${maintenanceDue ? 'text-amber-600 font-medium' : 'text-gray-600'}`}>
                        <span>Next Due:</span>
                        <span className="flex items-center gap-1">
                          {maintenanceDue && <AlertTriangle className="w-3 h-3" />}
                          {new Date(machine.next_maintenance_date).toLocaleDateString()}
                        </span>
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex gap-2 mt-4 pt-4 border-t border-gray-200">
                    <Button
                      variant="outline"
                      size="sm"
                      className="flex-1"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/mechanic/machines/${machine.id}`);
                      }}
                    >
                      View Details
                    </Button>
                    <Button
                      variant="default"
                      size="sm"
                      className="flex-1"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleLogMaintenance(machine.id);
                      }}
                    >
                      <Wrench className="w-3 h-3 mr-1" />
                      Log
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Results count */}
      {!isLoading && sortedMachines.length > 0 && (
        <p className="text-sm text-gray-500 text-center">
          Showing {sortedMachines.length} of {machines.length} machines
        </p>
      )}

      {/* Maintenance Log Modal */}
      <MaintenanceLogModal
        isOpen={isMaintenanceModalOpen}
        onClose={() => {
          setIsMaintenanceModalOpen(false);
          setSelectedMachineId(undefined);
        }}
        machineId={selectedMachineId}
      />
    </div>
  );
};

export default MachinesPage;

import React from 'react';
import { Card, CardHeader, CardContent, CardTitle, CardDescription } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Wrench, CheckCircle, Clock, Settings, Search, AlertTriangle } from 'lucide-react';
import { MachineFix } from '../../types';

interface MaintenanceTicketsProps {
    tickets: MachineFix[];
    isLoading: boolean;
    searchTerm: string;
    onSearchChange: (value: string) => void;
    onMarkFixed: (id: string) => void;
    onStartWork: (id: string) => void;
    isUpdating: boolean;
    showSOSOnly: boolean;
}

const MaintenanceTickets: React.FC<MaintenanceTicketsProps> = ({
    tickets,
    isLoading,
    searchTerm,
    onSearchChange,
    onMarkFixed,
    onStartWork,
    isUpdating,
    showSOSOnly
}) => {

    const getPriorityConfig = (priority: string) => {
        switch (priority) {
            case 'URGENT':
                return { label: 'URGENT', color: 'bg-red-100 text-red-700 border-red-200', pulse: true };
            case 'HIGH':
                return { label: 'High', color: 'bg-orange-100 text-orange-700 border-orange-200', pulse: false };
            case 'MEDIUM':
                return { label: 'Medium', color: 'bg-amber-100 text-amber-700 border-amber-200', pulse: false };
            case 'LOW':
            default:
                return { label: 'Low', color: 'bg-slate-100 text-slate-700 border-slate-200', pulse: false };
        }
    };

    const getStatusConfig = (status: string) => {
        switch (status) {
            case 'FIXED':
                return { label: 'Fixed', color: 'text-green-600 bg-green-50 border-green-200', icon: CheckCircle };
            case 'IN_PROGRESS':
                return { label: 'In Progress', color: 'text-blue-600 bg-blue-50 border-blue-200', icon: Settings };
            case 'REPORTED':
            default:
                return { label: 'Reported', color: 'text-amber-600 bg-amber-50 border-amber-200', icon: Clock };
        }
    };

    return (
        <Card className="border-cocoa-100 bg-white shadow-sm">
            <CardHeader className="border-b border-gray-100">
                <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                    <div>
                        <CardTitle className="text-cocoa-900 flex items-center gap-2">
                            {showSOSOnly && <AlertTriangle className="h-5 w-5 text-red-500" />}
                            {showSOSOnly ? 'SOS Alerts' : 'Maintenance Tickets'}
                        </CardTitle>
                        <CardDescription>
                            {tickets.length} {showSOSOnly ? 'urgent' : ''} issue{tickets.length !== 1 ? 's' : ''} found
                        </CardDescription>
                    </div>
                    <div className="relative w-full md:w-auto">
                        <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder="Search tickets..."
                            className="ps-8 w-full md:w-64 border-cocoa-200 focus:border-gold-500"
                            value={searchTerm}
                            onChange={(e) => onSearchChange(e.target.value)}
                        />
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                {isLoading ? (
                    <div className="text-center py-12 text-muted-foreground">
                        <div className="animate-spin h-8 w-8 border-2 border-gold-500 border-t-transparent rounded-full mx-auto mb-4"></div>
                        Loading tickets...
                    </div>
                ) : tickets.length === 0 ? (
                    <div className="text-center py-12 border-2 border-dashed border-gray-200 rounded-lg">
                        <Wrench className="h-12 w-12 text-slate-300 mx-auto mb-3" />
                        <p className="text-muted-foreground">
                            {showSOSOnly ? 'No urgent issues pending' : 'No maintenance tickets found'}
                        </p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {tickets.map(fix => {
                            const priorityConfig = getPriorityConfig(fix.priority);
                            const statusConfig = getStatusConfig(fix.status);
                            const StatusIcon = statusConfig.icon;

                            return (
                                <div 
                                    key={fix.id} 
                                    className={`border rounded-lg p-4 transition-all hover:shadow-md ${priorityConfig.color} ${priorityConfig.pulse ? 'animate-pulse-slow ring-1 ring-red-300' : ''}`}
                                >
                                    <div className="flex flex-col md:flex-row items-start justify-between gap-4">
                                        <div className="flex items-start gap-3 flex-1">
                                            <div className={`p-2 rounded-lg bg-white/50 backdrop-blur-sm shadow-sm`}>
                                                <Wrench className="h-5 w-5 text-cocoa-800" />
                                            </div>
                                            <div className="flex-1">
                                                <div className="flex items-center gap-2 flex-wrap mb-1">
                                                    <h3 className="font-bold text-lg text-cocoa-900">
                                                        {fix.machine_name ?? 'Unknown Machine'}
                                                    </h3>
                                                    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-bold uppercase tracking-wider bg-white/80 border ${priorityConfig.color.split(' ')[2] ?? 'border-gray-200'} text-gray-800 shadow-sm`}>
                                                        {priorityConfig.label}
                                                    </span>
                                                    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-semibold border ${statusConfig.color}`}>
                                                        <StatusIcon className="h-3 w-3 me-1" />
                                                        {statusConfig.label}
                                                    </span>
                                                </div>
                                                <p className="text-sm text-slate-800 font-medium mb-2">{fix.description}</p>
                                                {fix.notes && (
                                                    <div className="bg-white/40 p-2 rounded-md mb-2 border border-black/5">
                                                        <p className="text-xs text-slate-600 italic">
                                                            <span className="font-semibold not-italic">Tech Notes:</span> {fix.notes}
                                                        </p>
                                                    </div>
                                                )}
                                                <div className="flex items-center gap-4 text-xs text-slate-500 font-mono">
                                                    <span className="flex items-center gap-1">
                                                        <Clock className="h-3 w-3" />
                                                        Reported: {new Date(fix.created_at).toLocaleString()}
                                                    </span>
                                                    {fix.fixed_at && (
                                                        <span className="text-green-700 font-bold flex items-center gap-1">
                                                            <CheckCircle className="h-3 w-3" />
                                                            Fixed: {new Date(fix.fixed_at).toLocaleString()}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                        {fix.status !== 'FIXED' && (
                                            <div className="flex gap-2 w-full md:w-auto">
                                                {fix.status === 'REPORTED' && (
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="flex-1 md:flex-none border-blue-200 text-blue-700 hover:bg-blue-50 bg-white"
                                                        onClick={() => onStartWork(fix.id)}
                                                        disabled={isUpdating}
                                                    >
                                                        <Settings className="h-4 w-4 me-1" />
                                                        Start Work
                                                    </Button>
                                                )}
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    className="flex-1 md:flex-none border-green-200 text-green-700 hover:bg-green-50 bg-white"
                                                    onClick={() => onMarkFixed(fix.id)}
                                                    disabled={isUpdating}
                                                >
                                                    <CheckCircle className="h-4 w-4 me-1" />
                                                    Mark Fixed
                                                </Button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </CardContent>
        </Card>
    );
};

