                    </CardContent>
                </Card>
            )}

            {/* Issues List Component */}
            <MaintenanceTickets 
                tickets={filteredFixes}
                isLoading={loadingFixes || loadingSOS}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
                onMarkFixed={handleMarkAsFixed}
                onStartWork={handleMarkInProgress}
                isUpdating={isUpdating}
                showSOSOnly={showSOSOnly}
            />
        </div>
    );
};

export default MechanicDashboardPage;

import React, { useState, useEffect } from 'react';
import {
  AlertTriangle,
  Filter,
  Search,
  RefreshCw,
  Bell,
  Clock,
  CheckCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import SOSAlertCard from '../../components/mechanic/SOSAlertCard';
import ResolveAlertModal from '../../components/mechanic/ResolveAlertModal';
import { useMechanic } from '../../hooks/useMechanic';
import { SOSAlert, AlertPriority, AlertStatus } from '../../types';

type TabType = 'open' | 'in_progress' | 'resolved' | 'all';

const SOSAlertsPage: React.FC = () => {
  const { useSOSAlerts } = useMechanic();

  // State
  const [activeTab, setActiveTab] = useState<TabType>('open');
  const [searchQuery, setSearchQuery] = useState('');
  const [priorityFilter, setPriorityFilter] = useState<AlertPriority | 'all'>('all');
  const [selectedAlert, setSelectedAlert] = useState<SOSAlert | null>(null);
  const [isResolveModalOpen, setIsResolveModalOpen] = useState(false);

  // Fetch alerts based on active tab
  const statusFilter = activeTab === 'all' ? undefined : activeTab;
  const {
    data: rawAlerts = [],
    isLoading,
    refetch,
    isRefetching
  } = useSOSAlerts({
    status: statusFilter as AlertStatus | undefined,
    priority: priorityFilter === 'all' ? undefined : priorityFilter,
  });
  
  const alerts = Array.isArray(rawAlerts) ? rawAlerts : [];

  // Auto-refresh alerts every 15 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      void refetch();
    }, 15000);
    return () => clearInterval(interval);
  }, [refetch]);

  // Filter alerts by search query
  const filteredAlerts = alerts.filter((alert: SOSAlert) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      alert.machine_name?.toLowerCase().includes(query) ||
      alert.machine_code?.toLowerCase().includes(query) ||
      alert.problem_description.toLowerCase().includes(query)
    );
  });

  // Sort alerts by priority and time
  const sortedAlerts = [...filteredAlerts].sort((a, b) => {
    const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
    const priorityDiff = priorityOrder[a.priority] - priorityOrder[b.priority];
    if (priorityDiff !== 0) return priorityDiff;
    return new Date(b.reported_at).getTime() - new Date(a.reported_at).getTime();
  });

  const handleRespond = (alert: SOSAlert) => {
    setSelectedAlert(alert);
    setIsResolveModalOpen(true);
  };

  const handleAlertResolved = () => {
    setIsResolveModalOpen(false);
    setSelectedAlert(null);
    void refetch();
    toast.success('Alert updated successfully');
  };

  const tabs = [
    { id: 'open' as TabType, label: 'Open', icon: AlertTriangle, color: 'text-red-600' },
    { id: 'in_progress' as TabType, label: 'In Progress', icon: Clock, color: 'text-amber-600' },
    { id: 'resolved' as TabType, label: 'Resolved', icon: CheckCircle, color: 'text-green-600' },
    { id: 'all' as TabType, label: 'All', icon: Bell, color: 'text-gray-600' },
  ];

  const priorities: { value: AlertPriority | 'all'; label: string; color: string }[] = [
    { value: 'all', label: 'All Priorities', color: 'bg-gray-100 text-gray-700' },
    { value: 'critical', label: 'Critical', color: 'bg-red-100 text-red-700' },
    { value: 'high', label: 'High', color: 'bg-red-50 text-red-600' },
    { value: 'medium', label: 'Medium', color: 'bg-amber-100 text-amber-700' },
    { value: 'low', label: 'Low', color: 'bg-gray-100 text-gray-600' },
  ];

  // Count alerts by status for badges
  const { data: rawOpenAlerts = [] } = useSOSAlerts({ status: 'open' });
  const openAlerts = Array.isArray(rawOpenAlerts) ? rawOpenAlerts : [];
  
  const { data: rawInProgressAlerts = [] } = useSOSAlerts({ status: 'in_progress' });
  const inProgressAlerts = Array.isArray(rawInProgressAlerts) ? rawInProgressAlerts : [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader
        title="SOS Alerts"
        subtitle="Manage and respond to machine emergency alerts"
        actions={
          <Button
            variant="outline"
            onClick={() => { void refetch(); }}
            disabled={isRefetching}
            className="gap-2"
          >
            <RefreshCw className={`w-4 h-4 ${isRefetching ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
        }
      />

      {/* Stats Overview */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="bg-red-50 border-red-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-red-600 font-medium">Open Alerts</p>
                <p className="text-2xl font-bold text-red-800">{openAlerts.length}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-red-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-amber-600 font-medium">In Progress</p>
                <p className="text-2xl font-bold text-amber-800">{inProgressAlerts.length}</p>
              </div>
              <Clock className="w-8 h-8 text-amber-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-red-50 border-red-300">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-red-600 font-medium">Critical</p>
                <p className="text-2xl font-bold text-red-800">
                  {openAlerts.filter((a: SOSAlert) => a.priority === 'critical').length}
                </p>
              </div>
              <AlertTriangle className="w-8 h-8 text-red-500 animate-pulse" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-gray-600 font-medium">Total Today</p>
                <p className="text-2xl font-bold text-gray-800">{alerts.length}</p>
              </div>
              <Bell className="w-8 h-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <div className="flex gap-1">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const count = tab.id === 'open'
              ? openAlerts.length
              : tab.id === 'in_progress'
              ? inProgressAlerts.length
              : undefined;

            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-3 border-b-2 transition-colors ${
                  activeTab === tab.id
                    ? 'border-chocolate-600 text-chocolate-700 bg-chocolate-50'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                <Icon className={`w-4 h-4 ${activeTab === tab.id ? tab.color : ''}`} />
                <span className="font-medium">{tab.label}</span>
                {count !== undefined && count > 0 && (
                  <Badge
                    variant={tab.id === 'open' ? 'error' : 'warning'}
                    className="text-xs"
                  >
                    {count}
                  </Badge>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            type="text"
            placeholder="Search by machine name or code..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Priority Filter */}
        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-gray-400" />
          <select
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value as AlertPriority | 'all')}
            className="px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500 focus:border-chocolate-500 text-sm"
          >
            {priorities.map((p) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Alerts List */}
      <div className="space-y-4">
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="h-48 bg-gray-100 rounded-xl animate-pulse" />
            ))}
          </div>
        ) : sortedAlerts.length === 0 ? (
          <Card className="py-12">
            <CardContent className="text-center">
              <Bell className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-gray-700 mb-2">
                No alerts found
              </h3>
              <p className="text-gray-500">
                {activeTab === 'open'
                  ? 'Great news! There are no open alerts at this time.'
                  : searchQuery
                  ? 'No alerts match your search criteria.'
                  : `No ${activeTab.replace('_', ' ')} alerts to display.`}
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedAlerts.map((alert: SOSAlert) => (
              <SOSAlertCard
                key={alert.id}
                alert={alert}
                onRespond={() => handleRespond(alert)}
                onResolve={() => handleRespond(alert)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Results count */}
      {!isLoading && sortedAlerts.length > 0 && (
        <p className="text-sm text-gray-500 text-center">
          Showing {sortedAlerts.length} alert{sortedAlerts.length !== 1 ? 's' : ''}
        </p>
      )}

      {/* Resolve Modal */}
      {selectedAlert && (
        <ResolveAlertModal
          isOpen={isResolveModalOpen}
          onClose={() => {
            setIsResolveModalOpen(false);
            setSelectedAlert(null);
          }}
          alert={selectedAlert}
          onResolved={handleAlertResolved}
        />
      )}
    </div>
  );
};

export default SOSAlertsPage;

import { useEffect, useState } from 'react';
import { mechanicService } from '../../services/mechanicService';
import { MachineFix } from '../../types';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Wrench, CheckCircle2 } from 'lucide-react';
import { Input } from '../../components/ui/Input';

const MechanicPage = () => {
    const [logs, setLogs] = useState<MachineFix[]>([]);
    const [itemsLoading, setItemsLoading] = useState(true);

    useEffect(() => {
        const fetchLogs = async () => {
            try {
                const data = await mechanicService.getAllFixes();
                setLogs(data);
            } catch (error) {
                console.error('Failed to load fixes:', error);
            } finally {
                setItemsLoading(false);
            }
        };
        void fetchLogs();
    }, []);

    const isOpen = (status: MachineFix['status']) => status !== 'FIXED';

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold tracking-tight">Mechanic Maintenance Logs</h1>

             <Card className="bg-slate-50 border-slate-200">
                <CardHeader>
                    <CardTitle className="text-lg">Report New Issue</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex gap-4">
                        <Input placeholder="Machine ID (e.g. M-101)" className="w-40" />
                        <Input placeholder="Describe the issue..." className="flex-1" />
                        <Button className="bg-red-600 hover:bg-red-700">Report</Button>
                    </div>
                </CardContent>
            </Card>
            
            <div className="grid gap-4">
                {itemsLoading ? <p>Loading...</p> : logs.length === 0 ? (
                    <p className="text-muted-foreground">No maintenance logs found</p>
                ) : logs.map(log => (
                    <Card key={log.id} className={isOpen(log.status) ? 'border-l-4 border-l-red-500' : 'border-l-4 border-l-green-500'}>
                        <CardContent className="p-6 flex items-center justify-between">
                            <div className="flex items-start gap-4">
                                <div className={`p-3 rounded-full ${isOpen(log.status) ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                                    <Wrench className="h-6 w-6" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg">{log.machine_name ?? 'Unknown Machine'}</h3>
                                    <p className="text-slate-600">{log.description}</p>
                                    <p className="text-xs text-muted-foreground mt-1">
                                        Reported: {new Date(log.created_at).toLocaleString()} ΓÇó Status: {log.status}
                                    </p>
                                </div>
                            </div>
                            <div>
                                {isOpen(log.status) ? (
                                    <Button>Mark as Fixed</Button>
                                ) : (
                                    <span className="flex items-center gap-1 text-green-600 font-medium">
                                        <CheckCircle2 className="h-4 w-4" /> Resolved
                                    </span>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>
        </div>
    );
};

export default MechanicPage;

import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { useProduction } from '../../hooks/useProduction';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  Play, 
  Clock,
  FlaskConical,
  Flame,
  ThermometerSnowflake,
  Box,
  Loader2,
  ChevronRight
} from 'lucide-react';
import { toast } from 'sonner';
import { BatchStatus } from '../../types';

const BatchDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { useBatch, useUpdateBatchStatus } = useProduction();
  
  const { data: batch, isLoading } = useBatch(id!);
  const updateStatusMutation = useUpdateBatchStatus();

  const handleStatusUpdate = async (newStatus: BatchStatus) => {
    if (!batch) return;
    try {
      await updateStatusMutation.mutateAsync({ id: batch.id, status: newStatus });
      toast.success(`Batch updated to ${newStatus}`);
    } catch (error) {
      toast.error('Failed to update batch status.');
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-96 items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!batch) {
    return (
      <div className="text-center py-20">
        <h3 className="text-xl font-bold text-chocolate-900">Batch not found</h3>
        <Link to="/batches" className="text-chocolate-600 hover:text-chocolate-800 mt-2 inline-block font-medium">Back to list</Link>
      </div>
    );
  }

  const steps = [
    { status: 'pending', label: 'Draft', icon: Clock },
    { status: 'mixing', label: 'Mixing', icon: FlaskConical },
    { status: 'cooking', label: 'Cooking', icon: Flame },
    { status: 'cooling', label: 'Cooling', icon: ThermometerSnowflake },
    { status: 'packaging', label: 'Packaging', icon: Box },
    { status: 'completed', label: 'Completed', icon: CheckCircle2 },
  ];

  const currentStepIndex = steps.findIndex(s => s.status === batch.status);

  return (
    <div className="space-y-6 pb-20">
      <Link to="/batches" className="flex items-center gap-1 text-sm text-chocolate-600 hover:text-chocolate-900 transition-colors font-medium">
        <ArrowLeft className="w-4 h-4" /> Back to Batches
      </Link>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Progress & Controls */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-chocolate-50/50 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
            <div className="flex justify-between items-center mb-10 relative z-10">
              <div>
                <h1 className="text-3xl font-black text-chocolate-900 tracking-tight">Batch #{batch.batchNumber}</h1>
                <p className="text-sm font-medium text-chocolate-600 mt-1">{batch.recipeName ?? 'Premium Recipe'}</p>
              </div>
              <div className="text-right">
                <p className="text-[10px] text-chocolate-400 uppercase tracking-[0.2em] font-black">Planned Quantity</p>
                <div className="flex items-baseline justify-end gap-1">
                  <p className="text-3xl font-black text-chocolate-900">{batch.targetQuantity}</p>
                  <span className="text-xs font-bold text-chocolate-400 uppercase">UNITS</span>
                </div>
              </div>
            </div>

            {/* Stepper Progress */}
            <div className="relative mb-12">
              <div className="absolute top-5 left-0 right-0 h-1 bg-chocolate-50 rounded-full" />
              <div 
                className="absolute top-5 left-0 h-1 bg-gradient-to-r from-chocolate-500 to-gold-500 rounded-full transition-all duration-700 ease-out shadow-[0_0_10px_#cf9a3c]" 
                style={{ width: `${(currentStepIndex / (steps.length - 1)) * 100}%` }}
              />
              
              <div className="relative flex justify-between">
                {steps.slice(0, 6).map((step, idx) => {
                  const Icon = step.icon;
                  const isActive = idx === currentStepIndex;
                  const isCompleted = idx < currentStepIndex;
                  
                  return (
                    <div key={idx} className="flex flex-col items-center group cursor-default">
                      <div 
                        className={`w-10 h-10 rounded-full flex items-center justify-center z-10 border-2 transition-all duration-300 ${
                          isActive 
                            ? 'bg-chocolate-900 border-chocolate-900 text-gold-500 shadow-lg shadow-chocolate-900/30 scale-125' 
                            : isCompleted 
                              ? 'bg-chocolate-500 border-chocolate-500 text-white' 
                              : 'bg-white border-chocolate-100 text-chocolate-200'
                        }`}
                      >
                        {isCompleted ? <CheckCircle2 className="w-5 h-5" /> : <Icon className="w-5 h-5" />}
                      </div>
                      <span className={`mt-4 text-[10px] font-black uppercase tracking-widest transition-colors ${
                        isActive ? 'text-chocolate-900 translate-y-0 opacity-100' : 'text-chocolate-300'
                      }`}>
                        {step.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Interactive Area */}
            <div className="p-8 bg-chocolate-50/50 rounded-3xl border border-chocolate-100/50 relative overflow-hidden">
               <div className="absolute top-0 right-0 w-64 h-64 bg-white/40 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
               <h3 className="text-sm font-black text-chocolate-950 mb-6 uppercase tracking-widest relative z-10">Production Gateway</h3>
               
               {batch.status === 'completed' || batch.status === 'failed' ? (
                 <div className="text-center py-6 relative z-10">
                    <CheckCircle2 className={`w-16 h-16 mx-auto mb-4 ${batch.status === 'completed' ? 'text-emerald-500' : 'text-red-500'}`} />
                    <h4 className="text-2xl font-black capitalize text-chocolate-900">Batch {batch.status}</h4>
                    <p className="text-chocolate-500 mt-2 font-medium">Workflow cycle finalized.</p>
                 </div>
               ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 relative z-10">
                  {currentStepIndex < steps.length - 1 && (
                    <button 
                      onClick={() => handleStatusUpdate(steps[currentStepIndex + 1].status as BatchStatus)}
                      className="flex items-center justify-center gap-2 bg-chocolate-900 text-gold-500 py-4 rounded-xl font-black hover:bg-chocolate-800 transition-all shadow-lg shadow-chocolate-900/10 active:scale-[0.98] uppercase tracking-wide text-sm"
                    >
                      <Play className="w-4 h-4" />
                      Start {steps[currentStepIndex + 1].label}
                    </button>
                  )}
                  
                  <button 
                    onClick={() => handleStatusUpdate('completed')}
                    className="flex items-center justify-center gap-2 bg-emerald-600 text-white py-4 rounded-xl font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 active:scale-[0.98] uppercase tracking-wide text-sm"
                  >
                    <CheckCircle2 className="w-4 h-4" />
                    Quick Complete
                  </button>
                  
                  <button 
                    onClick={() => handleStatusUpdate('failed')}
                    className="flex items-center justify-center gap-2 bg-white border border-red-200 text-red-600 py-4 rounded-xl font-bold hover:bg-red-50 transition-all sm:col-span-2 uppercase tracking-wide text-sm hover:border-red-300"
                  >
                    <XCircle className="w-4 h-4" />
                    Abort & Quarantine
                  </button>
                </div>
               )}
            </div>
          </div>
        </div>

        {/* Info & Logs Column */}
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm">
             <h4 className="text-xs font-black text-chocolate-950 mb-6 uppercase tracking-[0.2em] border-b border-chocolate-50 pb-4">Specifications</h4>
             <dl className="space-y-5">
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Standard Operator</dt>
                  <dd className="text-sm font-bold text-chocolate-900 mt-1">Automatic Allocation</dd>
               </div>
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Assigned Production Line</dt>
                  <dd className="text-sm font-bold text-chocolate-900 mt-1">Central Processor #1</dd>
               </div>
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Batch Notes</dt>
                  <dd className="text-sm italic text-chocolate-700 mt-1 bg-chocolate-50 p-3 rounded-xl">"{batch.notes ?? 'No notes available'}"</dd>
               </div>
             </dl>
           </div>
           
           <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm">
             <h4 className="text-xs font-black text-chocolate-950 mb-6 uppercase tracking-[0.2em]">Quality Assurance</h4>
             <div className="p-6 bg-chocolate-50/50 rounded-2xl border border-dashed border-chocolate-200 text-center">
                <ShieldCheck className="w-8 h-8 text-gold-500 mx-auto mb-3" />
                <p className="text-xs text-chocolate-600 font-medium leading-relaxed mb-4">
                  QC inspections trigger automatically. Protocol V4.2 requires double-sampling.
                </p>
                <button className="text-chocolate-900 text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:text-gold-600 transition-colors mx-auto group">
                   Run Prevention Check <ChevronRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                </button>
             </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default BatchDetailPage;

import React, { useState } from 'react';
import { Search, Filter, Layers, PlayCircle } from 'lucide-react';
import { useProduction } from '../../hooks/useProduction';
import { useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import BatchCard from '../../components/production/BatchCard';
import { Batch } from '../../types';
import PageHeader from '../../components/layout/PageHeader';
import { motion } from 'framer-motion';

const BatchesPage: React.FC = () => {
  const navigate = useNavigate();
  const { useBatches } = useProduction();
  const [activeTab, setActiveTab] = useState<'all' | 'active' | 'completed' | 'failed'>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Map tab to API filter
  const statusFilter = activeTab === 'all' ? undefined : 
                       activeTab === 'active' ? 'in_progress' : 
                       activeTab;

  const { data: batchesData, isLoading } = useBatches({
    status: statusFilter as any,
    // search: searchQuery // Assuming API supports search
  });

  const batches = batchesData?.batches ?? [];

  const tabs = [
    { id: 'all', label: 'All Batches' },
    { id: 'active', label: 'In Progress' },
    { id: 'completed', label: 'Completed' },
    { id: 'failed', label: 'Failed' },
  ];

  return (
    <div className="space-y-8 pb-20">
      {/* Header */}
      {/* Header */}
      <PageHeader 
        title="Production Batches" 
        subtitle="Track manufacturing cycles, manage active runs, and review production history."
        actions={
          <Button 
            onClick={() => navigate('/production/recipes')} 
            className="bg-gradient-to-r from-chocolate-600 to-chocolate-800 text-white shadow-lg shadow-chocolate-900/20 hover:shadow-chocolate-900/40 transition-all active:scale-95"
          >
            <PlayCircle className="w-4 h-4 mr-2" />
            New Batch Run
          </Button>
        }
      />

      {/* Controls */}
      <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
        {/* Tabs */}
        <div className="flex p-1 bg-chocolate-100/50 rounded-xl border border-chocolate-100">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${
                activeTab === tab.id
                  ? 'bg-white text-chocolate-800 shadow-sm border border-chocolate-100'
                  : 'text-chocolate-600/70 hover:text-chocolate-800 hover:bg-white/50'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Search */}
        <div className="relative w-full md:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-chocolate-400" />
          <input
            type="text"
            placeholder="Search batches..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-white border border-chocolate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-gold-500/20 focus:border-gold-500 transition-all font-medium text-chocolate-900 placeholder:text-chocolate-300"
          />
        </div>
      </div>

      {/* Batches Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="h-48 bg-white rounded-3xl border border-chocolate-100 animate-pulse shadow-sm" />
          ))}
        </div>
      ) : batches.length > 0 ? (
        <motion.div 
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ staggerChildren: 0.1 }}
        >
          {batches.map((batch: Batch) => (
            <BatchCard key={batch.id} batch={batch} />
          ))}
        </motion.div>
      ) : (
        <div className="text-center py-20 bg-chocolate-50/30 rounded-3xl border border-dashed border-chocolate-200">
          <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm border border-chocolate-100">
            <Layers className="w-8 h-8 text-chocolate-300" />
          </div>
          <h3 className="text-lg font-bold text-chocolate-900">No batches found</h3>
          <p className="text-chocolate-500 mt-1 font-medium">
            {activeTab === 'all' 
              ? "Start production from the Recipes page." 
              : `No ${activeTab} batches found.`}
          </p>
        </div>
      )}
    </div>
  );
};

export default BatchesPage;

import { useState } from 'react';
import { useRecipes, useRecipeWithIngredients, useCreateBatch } from '../../services/productionService';
import { useIngredients } from '../../services/inventoryService';
import { useTranslate } from '../../services/aiService';
import { Recipe } from '../../types';
import { Card, CardHeader, CardContent, CardTitle, CardDescription } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { 
  ChefHat, 
  Play, 
  Package, 
  AlertCircle, 
  CheckCircle, 
  Clock,
  Sparkles,
  ArrowLeft,
  Languages,
  Loader2
} from 'lucide-react';

// Inline Translation Component for Production Instructions
const ProductionInstructionsWithTranslation = ({ instructions }: { instructions: string }) => {
    const [selectedLang, setSelectedLang] = useState<string>('');
    const { mutate: translate, isPending, data: translation } = useTranslate();

    const languages = [
        { code: 'ar', name: 'Arabic', flag: '≡ƒç╕≡ƒçª' },
        { code: 'am', name: 'Amharic', flag: '≡ƒç¬≡ƒç╣' },
        { code: 'ru', name: 'Russian', flag: '≡ƒç╖≡ƒç║' },
        { code: 'he', name: 'Hebrew', flag: '≡ƒç«≡ƒç▒' },
    ];

    const handleTranslate = (langCode: string) => {
        setSelectedLang(langCode);
        translate({
            text: instructions,
            targetLanguage: langCode,
            context: { domain: 'instruction' }
        });
    };

    return (
        <div>
            <div className="flex items-center justify-between mb-2">
                <label className="block text-sm font-medium text-cocoa-900">
                    Production Instructions
                </label>
                <div className="flex items-center gap-2">
                    <Languages className="h-4 w-4 text-gold-600" />
                    <span className="text-xs text-slate-600">Translate:</span>
                    {languages.map(lang => (
                        <button
                            key={lang.code}
                            onClick={() => handleTranslate(lang.code)}
                            disabled={isPending}
                            className={`px-2 py-1 text-xs rounded border transition-all ${
                                selectedLang === lang.code
                                    ? 'border-gold-500 bg-gold-50 text-gold-900'
                                    : 'border-slate-300 bg-white text-slate-700 hover:border-gold-400'
                            }`}
                            title={`Translate to ${lang.name}`}
                        >
                            {lang.flag}
                        </button>
                    ))}
                </div>
            </div>

            {/* Original Instructions */}
            <div className="bg-cocoa-50 border border-cocoa-100 rounded-md p-4 mb-3">
                <div className="flex items-center gap-2 mb-2">
                    <span className="text-xs font-semibold text-slate-600 uppercase">Original</span>
                </div>
                <p className="text-sm text-slate-700 whitespace-pre-wrap" dir="auto">
                    {instructions}
                </p>
            </div>

            {/* Translated Instructions */}
            {isPending && (
                <div className="bg-blue-50 border border-blue-200 rounded-md p-4 flex items-center gap-2">
                    <Loader2 className="h-4 w-4 animate-spin text-blue-600" />
                    <span className="text-sm text-blue-900">Translating with Gemini AI...</span>
                </div>
            )}

            {translation && selectedLang && !isPending && (
                <div className="bg-green-50 border border-green-200 rounded-md p-4">
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles className="h-4 w-4 text-green-600" />
                        <span className="text-xs font-semibold text-green-900 uppercase">
                            {languages.find(l => l.code === selectedLang)?.flag} {languages.find(l => l.code === selectedLang)?.name}
                        </span>
                    </div>
                    <p className="text-sm text-green-900 whitespace-pre-wrap font-medium" dir="auto">
                        {translation}
                    </p>
                </div>
            )}
        </div>
    );
};

type ProductionStep = 'select-recipe' | 'configure-batch' | 'confirm-ingredients';

const ProductionBatchPage = () => {
    const [currentStep, setCurrentStep] = useState<ProductionStep>('select-recipe');
    const [selectedRecipeId, setSelectedRecipeId] = useState<string | null>(null);
    const [batchQuantity, setBatchQuantity] = useState<number>(1);
    
    // React Query hooks
    const { data: recipes = [], isLoading: loadingRecipes } = useRecipes();
    const { data: recipeDetails, isLoading: loadingDetails } = useRecipeWithIngredients(selectedRecipeId ?? '');
    const { data: inventory = [] } = useIngredients();
    const { mutate: createBatch, isPending: isCreating } = useCreateBatch();

    const handleSelectRecipe = (recipe: Recipe) => {
        setSelectedRecipeId(recipe.id);
        setBatchQuantity(1);
        setCurrentStep('configure-batch');
    };

    const handleBack = () => {
        if (currentStep === 'configure-batch') {
            setCurrentStep('select-recipe');
            setSelectedRecipeId(null);
        } else if (currentStep === 'confirm-ingredients') {
            setCurrentStep('configure-batch');
        }
    };

    const handleContinue = () => {
        setCurrentStep('confirm-ingredients');
    };

    const handleStartBatch = () => {
        if (!selectedRecipeId) return;

        createBatch(
            {
                recipe_id: selectedRecipeId,
                quantity_produced: batchQuantity,
                notes: `Batch started via production dashboard`
            },
            {
                onSuccess: () => {
                    // Reset workflow
                    setCurrentStep('select-recipe');
                    setSelectedRecipeId(null);
                    setBatchQuantity(1);
                    alert('Batch created successfully!');
                },
                onError: (error) => {
                    alert(`Failed to create batch: ${error.message}`);
                },
            }
        );
    };

    // Calculate required ingredients
    const calculateRequirements = () => {
        if (!recipeDetails) return [];

        return recipeDetails.ingredients.map(ing => {
            const required = ing.quantity * batchQuantity;
            const available = inventory.find(i => i.id === ing.ingredient_id)?.current_stock ?? 0;
            const sufficient = available >= required;

            return {
                ...ing,
                required,
                available,
                sufficient
            };
        });
    };

    const requirements = calculateRequirements();
    const allIngredientsSufficient = requirements.every(r => r.sufficient);

    // Render recipe selection grid
    const renderRecipeSelection = () => (
        <div>
            <div className="mb-6">
                <h1 className="text-3xl font-bold tracking-tight font-serif text-cocoa-900">Production Dashboard</h1>
                <p className="text-muted-foreground">Select a recipe to start a new batch</p>
            </div>

            {loadingRecipes ? (
                <div className="text-center py-12 text-muted-foreground">
                    Loading recipes...
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {recipes.map(recipe => (
                        <Card 
                            key={recipe.id} 
                            className="border-cocoa-100 hover:border-gold-500 hover:shadow-lg transition-all cursor-pointer"
                            onClick={() => handleSelectRecipe(recipe)}
                        >
                            <CardHeader>
                                <div className="flex items-start justify-between">
                                    <ChefHat className="h-8 w-8 text-gold-600" />
                                    {recipe.is_active && (
                                        <span className="inline-flex items-center rounded-full bg-green-100 px-2 py-0.5 text-xs font-semibold text-green-700">
                                            Active
                                        </span>
                                    )}
                                </div>
                                <CardTitle className="text-cocoa-900 mt-2">{recipe.name}</CardTitle>
                                {recipe.code && (
                                    <p className="text-xs font-mono text-slate-500">{recipe.code}</p>
                                )}
                                <CardDescription className="line-clamp-2">
                                    {recipe.description ?? 'No description available'}
                                </CardDescription>
                            </CardHeader>
                            <CardContent>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-slate-600">Batch Size</span>
                                    <span className="font-semibold text-cocoa-900">
                                        {recipe.batch_size} {recipe.batch_unit}
                                    </span>
                                </div>
                                <Button 
                                    className="w-full mt-4 bg-gold-500 hover:bg-gold-600 text-white"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handleSelectRecipe(recipe);
                                    }}
                                >
                                    <Play className="h-4 w-4 me-2" />
                                    Start Batch
                                </Button>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );

    // Render batch configuration
    const renderBatchConfiguration = () => {
        const selectedRecipe = recipes.find(r => r.id === selectedRecipeId);
        if (!selectedRecipe) return null;

        return (
            <div className="max-w-2xl mx-auto">
                <Button 
                    variant="ghost" 
                    onClick={handleBack}
                    className="mb-4 -ms-2 text-cocoa-700"
                >
                    <ArrowLeft className="h-4 w-4 me-2" />
                    Back to recipes
                </Button>

                <Card className="border-cocoa-100">
                    <CardHeader>
                        <div className="flex items-center gap-3">
                            <div className="h-12 w-12 rounded-lg bg-gold-100 flex items-center justify-center">
                                <ChefHat className="h-6 w-6 text-gold-600" />
                            </div>
                            <div>
                                <CardTitle className="text-cocoa-900">{selectedRecipe.name}</CardTitle>
                                <CardDescription>Configure batch parameters</CardDescription>
                            </div>
                        </div>
                    </CardHeader>
                    <CardContent className="space-y-6">
                        {/* Batch Quantity */}
                        <div>
                            <label className="block text-sm font-medium text-cocoa-900 mb-2">
                                Batch Quantity
                            </label>
                            <div className="flex items-center gap-4">
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setBatchQuantity(Math.max(1, batchQuantity - 1))}
                                    className="border-cocoa-200"
                                >
                                    -
                                </Button>
                                <Input
                                    type="number"
                                    min="1"
                                    value={batchQuantity}
                                    onChange={(e) => setBatchQuantity(Math.max(1, Number(e.target.value)))}
                                    className="w-24 text-center border-cocoa-200"
                                />
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setBatchQuantity(batchQuantity + 1)}
                                    className="border-cocoa-200"
                                >
                                    +
                                </Button>
                                <span className="text-sm text-slate-600">
                                    ├ù {selectedRecipe.batch_size} {selectedRecipe.batch_unit} = {batchQuantity * selectedRecipe.batch_size} {selectedRecipe.batch_unit}
                                </span>
                            </div>
                        </div>


                        {/* Production Instructions with Translation */}
                        {selectedRecipe.instructions && (
                            <ProductionInstructionsWithTranslation instructions={selectedRecipe.instructions} />
                        )}

                        {/* Required Ingredients Preview */}
                        {loadingDetails ? (
                            <div className="text-center py-4 text-muted-foreground">
                                Loading ingredient requirements...
                            </div>
                        ) : (
                            <div>
                                <label className="block text-sm font-medium text-cocoa-900 mb-2">
                                    Required Ingredients ({recipeDetails?.ingredients.length ?? 0})
                                </label>
                                <div className="bg-slate-50 border border-slate-200 rounded-md p-3 space-y-2">
                                    {recipeDetails?.ingredients.map(ing => (
                                        <div key={ing.id} className="flex items-center justify-between text-sm">
                                            <span className="text-slate-700">{ing.ingredient_name ?? `Ingredient ${ing.ingredient_id}`}</span>
                                            <span className="font-medium text-cocoa-900">
                                                {ing.quantity * batchQuantity} {ing.unit}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        <Button
                            className="w-full bg-cocoa-700 hover:bg-cocoa-800 text-white"
                            onClick={handleContinue}
                            disabled={loadingDetails}
                        >
                            Continue to Ingredient Check
                        </Button>
                    </CardContent>
                </Card>
            </div>
        );
    };

    // Render ingredient confirmation
    const renderIngredientConfirmation = () => {
        const selectedRecipe = recipes.find(r => r.id === selectedRecipeId);
        if (!selectedRecipe) return null;

        return (
            <div className="max-w-3xl mx-auto">
                <Button 
                    variant="ghost" 
                    onClick={handleBack}
                    className="mb-4 -ms-2 text-cocoa-700"
                >
                    <ArrowLeft className="h-4 w-4 me-2" />
                    Back to configuration
                </Button>

                <Card className="border-cocoa-100">
                    <CardHeader>
                        <CardTitle className="text-cocoa-900">Confirm Ingredient Availability</CardTitle>
                        <CardDescription>
                            Review ingredient requirements vs. current stock
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-6">
                        {/* Status Banner */}
                        {allIngredientsSufficient ? (
                            <div className="flex items-center gap-3 bg-green-50 border border-green-200 rounded-md p-4">
                                <CheckCircle className="h-5 w-5 text-green-600 flex-shrink-0" />
                                <div>
                                    <p className="font-medium text-green-900">All ingredients available</p>
                                    <p className="text-sm text-green-700">You can proceed with batch creation</p>
                                </div>
                            </div>
                        ) : (
                            <div className="flex items-center gap-3 bg-amber-50 border border-amber-200 rounded-md p-4">
                                <AlertCircle className="h-5 w-5 text-amber-600 flex-shrink-0" />
                                <div>
                                    <p className="font-medium text-amber-900">Insufficient ingredients</p>
                                    <p className="text-sm text-amber-700">Some ingredients have insufficient stock</p>
                                </div>
                            </div>
                        )}

                        {/* Ingredient List */}
                        <div className="space-y-3">
                            {requirements.map((req, idx) => (
                                <div 
                                    key={idx} 
                                    className={`flex items-center justify-between p-4 rounded-md border ${
                                        req.sufficient 
                                            ? 'bg-white border-slate-200' 
                                            : 'bg-red-50 border-red-200'
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <Package className={`h-5 w-5 ${req.sufficient ? 'text-slate-400' : 'text-red-500'}`} />
                                        <div>
                                            <p className="font-medium text-cocoa-900">
                                                {req.ingredient_name ?? `Ingredient ${req.ingredient_id}`}
                                            </p>
                                            <p className="text-sm text-slate-600">
                                                Required: {req.required} {req.unit}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className={`font-semibold ${req.sufficient ? 'text-green-600' : 'text-red-600'}`}>
                                            {req.available} {req.unit}
                                        </p>
                                        <p className="text-xs text-slate-500">Available</p>
                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* Action Buttons */}
                        <div className="flex gap-3">
                            <Button
                                variant="outline"
                                className="flex-1 border-cocoa-200"
                                onClick={handleBack}
                            >
                                Adjust Quantity
                            </Button>
                            <Button
                                className={`flex-1 ${
                                    allIngredientsSufficient 
                                        ? 'bg-green-600 hover:bg-green-700' 
                                        : 'bg-amber-600 hover:bg-amber-700'
                                } text-white`}
                                onClick={handleStartBatch}
                                disabled={isCreating}
                            >
                                {isCreating ? (
                                    <>
                                        <Clock className="h-4 w-4 me-2 animate-spin" />
                                        Creating Batch...
                                    </>
                                ) : (
                                    <>
                                        <Sparkles className="h-4 w-4 me-2" />
                                        Start Production
                                    </>
                                )}
                            </Button>
                        </div>

                        {!allIngredientsSufficient && (
                            <p className="text-sm text-amber-700 text-center">
                                ΓÜá∩╕Å Warning: Starting with insufficient ingredients may cause production issues
                            </p>
                        )}
                    </CardContent>
                </Card>
            </div>
        );
    };

    return (
        <div className="space-y-6">
            {currentStep === 'select-recipe' && renderRecipeSelection()}
            {currentStep === 'configure-batch' && renderBatchConfiguration()}
            {currentStep === 'confirm-ingredients' && renderIngredientConfirmation()}
        </div>
    );
};

