export default RecipesPage;

import { useEffect, useState } from 'react';
import { qcService } from '../../services/qcService';
import { Batch } from '../../types';
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { ClipboardCheck, Check, X } from 'lucide-react';

const QCPage = () => {
    const [batches, setBatches] = useState<Batch[]>([]);
    const [loading, setLoading] = useState(true);
    const [notes, setNotes] = useState<Record<string, string>>({});

    useEffect(() => {
        const fetchBatches = async () => {
            try {
                const data = await qcService.getPendingBatches();
                setBatches(data);
            } catch (error) {
                console.error('Failed to load pending batches:', error);
            } finally {
                setLoading(false);
            }
        };
        void fetchBatches();
    }, []);

    const handleAction = async (id: string, status: 'APPROVED' | 'REJECTED') => {
        try {
            await qcService.updateQualityStatus(id, {
                batch_id: id,
                status,
                notes: notes[id] ?? ''
            });
            // Optimistic update
            setBatches(prev => prev.filter(b => b.id !== id));
        } catch (error) {
            console.error('Failed to update status:', error);
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold tracking-tight">Quality Control</h1>
            <p className="text-muted-foreground">Verify production batches before release.</p>

            {loading ? (
                <div className="text-center py-10 text-muted-foreground">Loading...</div>
            ) : (
                <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                    {batches.length === 0 ? (
                        <div className="col-span-full text-center py-10 text-muted-foreground">
                            No batches pending Quality Control.
                        </div>
                    ) : batches.map(batch => (
                        <Card key={batch.id} className="border-yellow-200 bg-yellow-50/20">
                             <CardHeader className="pb-2">
                                 <div className="flex items-center gap-2 text-yellow-800">
                                     <ClipboardCheck className="h-5 w-5" />
                                     <CardTitle className="text-lg">Batch #{batch.batch_number ?? batch.id}</CardTitle>
                                 </div>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div>
                                    <div className="text-2xl font-bold">{batch.recipe_name ?? 'Unknown Recipe'}</div>
                                    <div className="text-sm text-slate-600">{batch.quantity_produced} Units</div>
                                </div>
                                
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">QC Notes</label>
                                    <Input 
                                        placeholder="Enter findings..." 
                                        value={notes[batch.id] ?? ''}
                                        onChange={(e) => setNotes({...notes, [batch.id]: e.target.value})}
                                    />
                                </div>
                            </CardContent>
                            <CardFooter className="gap-2">
                                <Button 
                                    className="w-full bg-red-100 text-red-700 hover:bg-red-200" 
                                    variant="ghost"
                                    onClick={() => void handleAction(batch.id, 'REJECTED')}
                                >
                                    <X className="h-4 w-4 mr-2" /> Reject
                                </Button>
                                <Button 
                                    className="w-full bg-green-600 hover:bg-green-700"
                                    onClick={() => void handleAction(batch.id, 'APPROVED')}
                                >
                                    <Check className="h-4 w-4 mr-2" /> Approve
                                </Button>
                            </CardFooter>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

export default QCPage;

import React from 'react';
import { Card, CardHeader, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { 
  ClipboardCheck, 
  CheckCircle2, 
  XCircle, 
  AlertCircle, 
  Search
} from 'lucide-react';
import { QualityControl } from '../../types';

interface QualityChecksProps {
    checks: QualityControl[];
    isLoading: boolean;
    searchTerm: string;
    onSearchChange: (value: string) => void;
    onApprove: (id: string) => void;
    onReject: (id: string) => void;
    isUpdating: boolean;
}

const QualityChecks: React.FC<QualityChecksProps> = ({
    checks,
    isLoading,
    searchTerm,
    onSearchChange,
    onApprove,
    onReject,
    isUpdating
}) => {
    
    // Helper for status config
    const getStatusConfig = (status: string) => {
        switch (status) {
            case 'APPROVED':
                return {
                    label: 'Approved',
                    color: 'bg-green-50 border-green-200 text-green-700',
                    icon: CheckCircle2,
                    iconColor: 'text-green-600'
                };
            case 'REJECTED':
                return {
                    label: 'Rejected',
                    color: 'bg-red-50 border-red-200 text-red-700',
                    icon: XCircle,
                    iconColor: 'text-red-600'
                };
            case 'PENDING':
            default:
                return {
                    label: 'Pending',
                    color: 'bg-amber-50 border-amber-200 text-amber-700',
                    icon: AlertCircle,
                    iconColor: 'text-amber-600'
                };
        }
    };

    return (
        <Card className="bg-slate-900 border-slate-800">
            <CardHeader className="border-b border-slate-800 pb-4">
                <div className="flex items-center justify-between">
                     <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                        <ClipboardCheck className="h-5 w-5 text-gold-500" />
                        Inspection Log
                    </h3>
                    <div className="relative w-full max-w-sm">
                        <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-slate-500" />
                        <Input
                            placeholder="Search batch ID or notes..."
                            className="ps-8 bg-slate-950 border-slate-800 text-slate-200 focus:border-gold-500 placeholder:text-slate-600"
                            value={searchTerm}
                            onChange={(e) => onSearchChange(e.target.value)}
                        />
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                {isLoading ? (
                    <div className="text-center py-12 text-slate-500">
                        <div className="animate-spin h-8 w-8 border-2 border-gold-500 border-t-transparent rounded-full mx-auto mb-4"></div>
                        Loading quality checks...
                    </div>
                ) : checks.length === 0 ? (
                    <div className="text-center py-12 border-2 border-dashed border-slate-800 rounded-lg">
                        <ClipboardCheck className="h-12 w-12 text-slate-700 mx-auto mb-3" />
                        <p className="text-slate-500">No quality checks found</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {checks.map(check => {
                            const statusConfig = getStatusConfig(check.status);
                            const StatusIcon = statusConfig.icon;

                            return (
                                <div key={check.id} className={`border rounded-lg p-4 transition-all hover:bg-slate-800/30 ${statusConfig.color.replace('bg-', 'hover:bg-opacity-10 border-')}`}>
                                    <div className="flex items-start justify-between">
                                        <div className="flex items-start gap-4">
                                            <div className={`p-3 rounded-xl bg-white/5`}>
                                                <StatusIcon className={`h-6 w-6 ${statusConfig.iconColor}`} />
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-2 mb-1">
                                                    <span className="font-mono text-gold-500 font-bold">
                                                        {check.batch_id}
                                                    </span>
                                                    <span className={`px-2 py-0.5 rounded-full text-[10px] uppercase font-bold tracking-wider border ${statusConfig.color}`}>
                                                        {statusConfig.label}
                                                    </span>
                                                </div>
                                                
                                                {check.notes && (
                                                    <p className="text-sm text-slate-400 mb-2 italic">"{check.notes}"</p>
                                                )}
                                                
                                                <div className="flex items-center gap-4 text-xs text-slate-500 mt-2">
                                                    <span>User: {check.checked_by.slice(0,8)}</span>
                                                    <span>ΓÇó</span>
                                                    <span>{new Date(check.created_at).toLocaleString()}</span>
                                                    {check.defect_count > 0 && (
                                                        <>
                                                            <span>ΓÇó</span>
                                                            <span className="text-red-400 font-bold flex items-center gap-1">
                                                                <AlertCircle className="h-3 w-3" />
                                                                {check.defect_count} Defects
                                                            </span>
                                                        </>
                                                    )}
                                                </div>
                                            </div>
                                        </div>

                                        {check.status === 'PENDING' && (
                                            <div className="flex flex-col gap-2">
                                                <Button
                                                    size="sm"
                                                    className="bg-green-600 hover:bg-green-700 text-white border-none w-24"
                                                    onClick={() => onApprove(check.id)}
                                                    disabled={isUpdating}
                                                >
                                                    <CheckCircle2 className="h-4 w-4 me-1" />
                                                    Pass
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    className="text-red-400 hover:text-red-300 hover:bg-red-950/30 w-24"
                                                    onClick={() => onReject(check.id)}
                                                    disabled={isUpdating}
                                                >
                                                    <XCircle className="h-4 w-4 me-1" />
                                                    Reject
                                                </Button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </CardContent>
        </Card>
    );
};

export default QualityChecks;

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardHeader, CardContent, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Select } from '../../components/ui/Select';
import { Textarea } from '../../components/ui/Textarea';
import { Badge } from '../../components/ui/Badge';
import { 
  Bot, 
  Sparkles, 
  Save,
  Loader2,
  Plus,
  Trash2,
  ChefHat
} from 'lucide-react';
import { toast } from 'sonner';
import { useProduction } from '../../hooks/useProduction';
import { useInventory } from '../../hooks/useInventory';

// Types for form state
interface RecipeFormState {
  name: string;
  description: string;
  yield_quantity: number;
  yield_unit: string;
  duration_minutes: number;
  difficulty_level: 'easy' | 'medium' | 'hard';
  category: string;
  instructions: string;
}

interface IngredientEntry {
  tempId: string; // for key
  ingredient_id: string; // from inventory
  name: string; // display name
  amount: string; // string mainly for input, parsed to number
  unit: string;
  notes: string;
}

const CreateRecipe = () => {
    const navigate = useNavigate();
    const { useCreateRecipe } = useProduction();
    const createRecipe = useCreateRecipe();
    
    // Inventory Data for dropdown
    const { useInventoryItems } = useInventory();
    const { data: inventoryData } = useInventoryItems({ limit: 100 }); // Increase limit to show more items
    const inventoryItems = inventoryData?.items ?? [];

    // AI State
    const [prompt, setPrompt] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);

    // Form State
    const [formData, setFormData] = useState<RecipeFormState>({
      name: '',
      description: '',
      yield_quantity: 100,
      yield_unit: 'kg',
      duration_minutes: 60,
      difficulty_level: 'medium',
      category: 'bars',
      instructions: ''
    });

    const [ingredients, setIngredients] = useState<IngredientEntry[]>([]);

    // New Ingredient State
    const [newIngredient, setNewIngredient] = useState<IngredientEntry>({
      tempId: '',
      ingredient_id: '',
      name: '',
      amount: '',
      unit: 'kg',
      notes: ''
    });

    // --- AI Handler ---
    const handleGenerate = async () => {
        if (!prompt) return;
        setIsGenerating(true);
        try {
            // Simulate AI Generation
            await new Promise(resolve => setTimeout(resolve, 2500));
            
            const generatedName = 'AI Generated: ' + prompt.split(' ').slice(0, 3).join(' ') + '...';
            const generatedDesc = `Optimized formulation for ${prompt}. Focused on cost-efficiency and texture stability.`;
            
            // Update Form
            setFormData(prev => ({
              ...prev,
              name: generatedName,
              description: generatedDesc,
              instructions: `1. Melt cocoa mass at 50┬░C.\n2. Mix in sugar and emulsifiers.\n3. Refine to 20 microns.\n4. Conche for 12 hours.\n5. Temper and mold.`
            }));

            // Mock Ingredients - In a real app, AI would return structured data we'd map to inventory
            const mockIngredients: IngredientEntry[] = [
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Cocoa Mass', amount: '50', unit: 'kg', notes: 'Fino de Aroma' },
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Sugar', amount: '35', unit: 'kg', notes: 'Fine white' },
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Cocoa Butter', amount: '15', unit: 'kg', notes: 'Deodorized' }
            ];
            setIngredients(mockIngredients);

            toast.success("Recipe generated by AI! Review and edit details below.");
        } catch {
            toast.error("Generation failed");
        } finally {
            setIsGenerating(false);
        }
    };

    // --- Ingredient Handlers ---
    const handleAddIngredient = () => {
      // Basic validation
      if (!newIngredient.name && !newIngredient.ingredient_id) {
        toast.error("Please select an ingredient or enter a name");
        return;
      }
      if (!newIngredient.amount || isNaN(parseFloat(newIngredient.amount))) {
        toast.error("Please enter a valid amount");
        return;
      }

      setIngredients([...ingredients, { ...newIngredient, tempId: crypto.randomUUID() }]);
      
      // Reset form
      setNewIngredient({
        tempId: '',
        ingredient_id: '',
        name: '', 
        amount: '',
        unit: 'kg',
        notes: ''
      });
      toast.success("Ingredient added");
    };

    const handleRemoveIngredient = (tempId: string) => {
      setIngredients(ingredients.filter(i => i.tempId !== tempId));
    };

    const handleInventorySelect = (itemId: string) => {
      const item = inventoryItems.find(i => i.id === itemId);
      if (item) {
        setNewIngredient(prev => ({
          ...prev,
          ingredient_id: item.id,
          name: item.name,
          unit: item.unit 
        }));
      } else {
         setNewIngredient(prev => ({ ...prev, ingredient_id: itemId, name: '' }));
      }
    };

    // --- Save Handler ---
    const handleSave = () => {
        if (!formData.name) {
          toast.error("Recipe name is required");
          return;
        }

        const recipePayload = {
          name: formData.name,
          description: formData.description,
          category: formData.category,
          yield_quantity: formData.yield_quantity,
          yield_unit: formData.yield_unit,
          duration_minutes: formData.duration_minutes,
          difficulty_level: formData.difficulty_level,
          instructions: formData.instructions,
          is_active: true,
          ingredients: ingredients.map(ing => ({
            inventory_item_id: ing.ingredient_id ?? null,
            custom_name: ing.ingredient_id ? null : ing.name,
            quantity: parseFloat(ing.amount),
            unit: ing.unit,
            notes: ing.notes
          }))
        };

        createRecipe.mutate(recipePayload as any, {
            onSuccess: () => {
                toast.success("Recipe saved successfully!");
                navigate('/production/recipes');
            },
            onError: (err) => {
                console.error(err);
                toast.error("Failed to save recipe");
            }
        });
    };

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-12 animate-fade-in px-4">
            {/* Header / AI Prompt */}
            <div className="text-center space-y-4 pt-8">
                <div className="bg-gold-100 p-4 rounded-full w-fit mx-auto animate-bounce-slow">
                    <Sparkles className="h-8 w-8 text-gold-600" />
                </div>
                <h1 className="text-4xl font-bold font-serif text-cocoa-900">Formulation Architect</h1>
                <p className="text-xl text-slate-600 max-w-2xl mx-auto italic font-serif">
                   "Mastering the alchemy of chocolate, one ingredient at a time."
                </p>
            </div>

            <Card className="border-gold-200 shadow-xl border-2 bg-gradient-to-br from-white to-gold-50/30 overflow-hidden">
                <div className="h-2 bg-gold-400 w-full" />
                <CardContent className="pt-8">
                    <div className="flex flex-col md:flex-row gap-4">
                        <Input 
                            placeholder="Describe a new chocolate creation (e.g. '70% Dark with Sea Salt')..." 
                            className="flex-1 h-14 text-lg border-gold-200 focus:ring-gold-500 bg-white"
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && void handleGenerate()}
                        />
                        <Button 
                            className="h-14 px-8 bg-gold-600 hover:bg-gold-700 text-white text-lg font-bold shadow-lg transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2"
                            onClick={() => void handleGenerate()}
                            disabled={isGenerating || !prompt}
                        >
                            {isGenerating ? <Loader2 className="h-6 w-6 animate-spin" /> : <Bot className="h-6 w-6" />}
                            {isGenerating ? "Generating..." : "AI Generate"}
                        </Button>
                    </div>
                </CardContent>
            </Card>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Recipe Details */}
                <div className="lg:col-span-2 space-y-8">
                    <Card className="border-cocoa-100 shadow-md">
                        <CardHeader className="bg-cocoa-50/30 border-b border-cocoa-100">
                            <CardTitle className="text-xl text-cocoa-900 flex items-center gap-2">
                                <ChefHat className="w-6 h-6 text-gold-600" />
                                Recipe Blueprint
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-6 space-y-6">
                            <Input 
                                label="Recipe Title"
                                value={formData.name}
                                onChange={(e) => setFormData({...formData, name: e.target.value})}
                                placeholder="e.g., Mountain Peak Dark Truffle"
                                required
                            />
                            
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <Select 
                                    label="Category"
                                    value={formData.category}
                                    onChange={(e) => setFormData({...formData, category: e.target.value})}
                                    options={[
                                        { label: "Bars", value: "bars" },
                                        { label: "Truffles", value: "truffles" },
                                        { label: "Bonbons", value: "bonbons" },
                                        { label: "Gift Boxes", value: "gift_boxes" },
                                        { label: "Pralines", value: "pralines" }
                                    ]}
                                />
                                <Select 
                                    label="Difficulty Level"
                                    value={formData.difficulty_level}
                                    onChange={(e) => setFormData({...formData, difficulty_level: e.target.value as any})}
                                    options={[
                                        { label: "Easy - Apprentice", value: "easy" },
                                        { label: "Medium - Artisan", value: "medium" },
                                        { label: "Hard - Master", value: "hard" }
                                    ]}
                                />
                            </div>

                            <div className="grid grid-cols-3 gap-4">
                                <Input 
                                    label="Yield Qty"
                                    type="number"
                                    value={formData.yield_quantity}
                                    onChange={(e) => setFormData({...formData, yield_quantity: parseFloat(e.target.value)})}
                                />
                                <Select 
                                    label="Yield Unit"
                                    value={formData.yield_unit}
                                    onChange={(e) => setFormData({...formData, yield_unit: e.target.value})}
                                    options={[
                                        { label: "kg", value: "kg" },
                                        { label: "g", value: "g" },
                                        { label: "pcs", value: "pcs" },
                                        { label: "units", value: "units" }
                                    ]}
                                />
                                <Input 
                                    label="Time (min)"
                                    type="number"
                                    value={formData.duration_minutes}
                                    onChange={(e) => setFormData({...formData, duration_minutes: parseFloat(e.target.value)})}
                                />
                            </div>

                            <Textarea 
                                label="Description"
                                value={formData.description}
                                onChange={(e) => setFormData({...formData, description: e.target.value})}
                                placeholder="The sensory profile and intended audience for this masterpiece..."
                            />

                            <Textarea 
                                label="Preparation Instructions"
                                className="min-h-[200px] font-mono text-sm leading-relaxed"
                                value={formData.instructions}
                                onChange={(e) => setFormData({...formData, instructions: e.target.value})}
                                placeholder="1. Temper the chocolate to 31┬░C...\n2. Prepare the ganache center..."
                            />
                        </CardContent>
                    </Card>
                </div>

                {/* Right Column: Ingredients */}
                <div className="space-y-6">
                    <Card className="border-cocoa-100 shadow-md">
                        <CardHeader className="bg-cocoa-50/30 border-b border-cocoa-100">
                             <CardTitle className="text-lg text-cocoa-900 flex items-center justify-between">
                                <span>Ingredient Vault</span>
                                <Badge className="bg-gold-600">{ingredients.length}</Badge>
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-4 space-y-6">
                            {/* Ingredients List */}
                            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                {ingredients.length === 0 ? (
                                    <div className="text-center py-12 text-slate-400 text-sm italic bg-slate-50/50 rounded-lg border border-dashed border-slate-200">
                                        No materials selected yet.
                                    </div>
                                ) : (
                                    ingredients.map((ing) => (
                                        <div key={ing.tempId} className="flex justify-between items-center p-3 bg-white rounded-lg border border-slate-200 shadow-sm group hover:border-gold-300 transition-all">
                                            <div>
                                                <div className="font-bold text-cocoa-900">{ing.name}</div>
                                                <div className="text-xs text-cocoa-600 flex items-center gap-2">
                                                    <span className="font-mono bg-gold-50 text-gold-700 px-1.5 py-0.5 rounded">{ing.amount}{ing.unit}</span>
                                                    {ing.notes && <span className="truncate max-w-[120px]">ΓÇó {ing.notes}</span>}
                                                </div>
                                            </div>
                                            <Button 
                                                variant="ghost" 
                                                size="sm" 
                                                onClick={() => handleRemoveIngredient(ing.tempId)}
                                                className="h-8 w-8 p-0 text-slate-300 hover:text-red-500"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))
                                )}
                            </div>

                            {/* Add Ingredient Card (Requested User Feature) */}
                            <div className="p-4 rounded-xl border-2 border-dashed border-gold-300 bg-gold-50/20 space-y-4 shadow-inner relative">
                                <div className="absolute -top-3 left-4 bg-white px-2 py-0.5 border border-gold-300 rounded text-[10px] font-bold text-gold-600 uppercase">
                                    Ingredient Card
                                </div>
                                
                                <Select 
                                    label="Selection"
                                    value={newIngredient.ingredient_id}
                                    onChange={(e) => handleInventorySelect(e.target.value)}
                                    options={[
                                        { label: "Choose from Inventory...", value: "" },
                                        ...inventoryItems.map(item => ({ 
                                            label: `${item.name} (${item.quantity} ${item.unit} available)`, 
                                            value: item.id 
                                        }))
                                    ]}
                                />

                                {!newIngredient.ingredient_id && (
                                    <Input 
                                        label="Custom Name"
                                        placeholder="Enter name for manual entry..."
                                        value={newIngredient.name}
                                        onChange={(e) => setNewIngredient({...newIngredient, name: e.target.value, ingredient_id: ''})}
                                    />
                                )}

                                <div className="grid grid-cols-2 gap-3">
                                    <Input 
                                        label="Amount" 
                                        type="number" 
                                        placeholder="0.00"
                                        value={newIngredient.amount}
                                        onChange={(e) => setNewIngredient({...newIngredient, amount: e.target.value})}
                                    />
                                    <Select 
                                        label="Unit"
                                        value={newIngredient.unit}
                                        onChange={(e) => setNewIngredient({...newIngredient, unit: e.target.value})}
                                        options={[
                                            { label: "kg", value: "kg" },
                                            { label: "g", value: "g" },
                                            { label: "L", value: "L" },
                                            { label: "pcs", value: "pcs" },
                                            { label: "units", value: "units" }
                                        ]}
                                    />
                                </div>

                                <Input 
                                    label="Notes / Description"
                                    placeholder="e.g. melted, room temp..."
                                    value={newIngredient.notes}
                                    onChange={(e) => setNewIngredient({...newIngredient, notes: e.target.value})}
                                />

                                <Button 
                                    onClick={handleAddIngredient} 
                                    className="w-full bg-cocoa-900 hover:bg-black text-gold-100 h-10 font-bold shadow-md hover:shadow-lg transition-all"
                                    disabled={!newIngredient.name && !newIngredient.ingredient_id}
                                >
                                    <Plus className="w-4 h-4 mr-2" />
                                    Add Ingredient
                                </Button>
                            </div>
                        </CardContent>
                    </Card>

                    <Button 
                        onClick={handleSave} 
                        className="w-full h-14 bg-green-600 hover:bg-green-700 text-white text-xl font-bold shadow-xl flex items-center justify-center gap-3 transition-all hover:scale-[1.02] active:scale-95"
                        disabled={createRecipe.isPending}
                    >
                        {createRecipe.isPending ? <Loader2 className="w-6 h-6 animate-spin" /> : <Save className="w-6 h-6" />}
                        Archive Recipe
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default CreateRecipe;

import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import { 
  ArrowLeft, 
  ChefHat, 
  Clock, 
  Bot, 
  CheckCircle2,
  Trash2,
  Edit,
  PlayCircle,
  AlertCircle
} from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { Recipe, RecipeIngredient } from '../../types';
import { fetchRecipeById } from '../../services/recipeService';
import { toast } from 'sonner';
import StartBatchModal from '../../components/production/StartBatchModal';

const RecipeDetails = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const [translatedInstructions, setTranslatedInstructions] = useState<string | null>(null);
    const [isTranslating, setIsTranslating] = useState(false);
    const [isBatchModalOpen, setIsBatchModalOpen] = useState(false);

    const { data: recipe, isLoading } = useQuery<Recipe>({
        queryKey: ['recipe', id],
        queryFn: () => fetchRecipeById(id ?? ''),
        enabled: !!id
    });

    const handleTranslate = async (lang: string) => {
        if (!recipe?.instructions) return;
        
        setIsTranslating(true);
        try {
            const baseInstructions = Array.isArray(recipe.instructions) ? recipe.instructions.join('\n') : recipe.instructions;
            const token = localStorage.getItem('token');
            const API_BASE = import.meta.env.VITE_API_URL ?? 'http://localhost:5000/api';
            const res = await fetch(`${API_BASE}/ai/translate`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                },
                body: JSON.stringify({
                    text: baseInstructions,
                    targetLanguage: lang,
                    context: { domain: 'recipe' }
                })
            });

            if (!res.ok) throw new Error(`Translation API returned ${res.status}`);
            const data = await res.json();
            const translated = data?.data?.translation ?? data?.translation ?? baseInstructions;
            setTranslatedInstructions(translated);
            toast.success(`Instructions translated to ${lang.toUpperCase()}`);
        } catch (err: unknown) {
            console.error('Translation failed:', err);
            const message = err instanceof Error ? err.message : 'Translation service unavailable';
            toast.error(message);
        } finally {
            setIsTranslating(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex h-96 items-center justify-center">
                <div className="animate-spin h-8 w-8 border-4 border-gold-500 border-t-transparent rounded-full" />
                <span className="ml-4 font-bold text-chocolate-900/40 uppercase tracking-widest text-xs">Accessing Formulation...</span>
            </div>
        );
    }

    if (!recipe) {
        return (
            <div className="text-center py-20 bg-white/30 rounded-3xl border border-white/40 backdrop-blur-sm">
                <AlertCircle className="h-12 w-12 text-chocolate-200 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-chocolate-900">Formulation Not Found</h2>
                <Button 
                    onClick={() => navigate('/recipes')}
                    className="mt-6 bg-chocolate-900 text-white"
                >
                    Return to Library
                </Button>
            </div>
        );
    }

    return (
        <div className="space-y-8 pb-20 animate-fade-in max-w-6xl mx-auto">
            {/* Top Navigation & Actions */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                <button 
                    onClick={() => navigate('/recipes')}
                    className="group flex items-center gap-2 text-sm font-bold text-chocolate-900/40 hover:text-chocolate-900 transition-colors uppercase tracking-[0.2em]"
                >
                    <div className="p-1.5 rounded-full bg-white border border-chocolate-900/10 group-hover:border-chocolate-900/30 transition-colors">
                        <ArrowLeft className="w-4 h-4" /> 
                    </div>
                    Back to Library
                </button>

                <div className="flex items-center gap-3">
                    <button className="p-3 text-chocolate-900/40 hover:text-vibrant-red hover:bg-vibrant-red/10 rounded-2xl transition-all">
                        <Trash2 className="w-5 h-5" />
                    </button>
                    <button className="flex items-center gap-2 px-6 py-3 bg-white border border-chocolate-100 text-chocolate-900 font-bold rounded-2xl hover:bg-chocolate-50 shadow-sm transition-all">
                        <Edit className="w-4 h-4" />
                        Modify
                    </button>
                    <button 
                        onClick={() => setIsBatchModalOpen(true)}
                        className="flex items-center gap-2 px-8 py-3 bg-chocolate-900 text-white font-bold rounded-2xl hover:bg-chocolate-800 shadow-xl shadow-chocolate-900/20 transition-all hover:scale-[1.02] active:scale-[0.98]"
                    >
                        <PlayCircle className="w-5 h-5" />
                        Execute Batch
                    </button>
                </div>
            </div>

            {/* Hero Section - Magazine Style */}
            <div className="relative group rounded-[3rem] overflow-hidden bg-white border border-chocolate-100/50 shadow-2xl shadow-chocolate-950/5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-0">
                    {/* Left side: Metadata & Title */}
                    <div className="p-12 md:p-16 flex flex-col justify-center">
                        <div className="flex items-center gap-2 mb-6">
                            <span className="h-px w-10 bg-gold-500/50"></span>
                            <span className="text-[10px] font-black tracking-[0.4em] text-gold-600 uppercase">Production Protocol 04</span>
                        </div>
                        
                        <h1 className="text-5xl md:text-6xl font-black text-chocolate-950 tracking-tight leading-[1.1] mb-6">
                            {recipe.name}
                        </h1>
                        
                        <div className="flex flex-wrap items-center gap-6 mb-8 pt-4">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-chocolate-900/30 uppercase tracking-widest mb-1">Recipe SKU</span>
                                <span className="text-sm font-bold text-chocolate-900 font-mono italic">{recipe.code ?? 'UNASSIGNED'}</span>
                            </div>
                            <div className="w-px h-8 bg-chocolate-100/50" />
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-chocolate-900/30 uppercase tracking-widest mb-1">Standard Duration</span>
                                <span className="text-sm font-bold text-chocolate-900 flex items-center gap-1.5 leading-none">
                                    <Clock className="w-4 h-4 text-gold-500" /> {recipe.duration_minutes} Minutes
                                </span>
                            </div>
                             <div className="w-px h-8 bg-chocolate-100/50" />
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-chocolate-900/30 uppercase tracking-widest mb-1">Difficulty</span>
                                <span className="text-sm font-bold text-chocolate-900 uppercase tracking-wider leading-none">
                                    {recipe.difficulty_level ?? 'ADVANCED'}
                                </span>
                            </div>
                        </div>

                        <p className="text-lg text-chocolate-900/60 font-medium leading-relaxed italic max-w-md">
                            "{recipe.description ?? 'A masterpiece of balanced bitterness and velvety texture, engineered for precision tempering and artisanal finish.'}"
                        </p>
                    </div>

                    {/* Right side: Image Hero */}
                    <div className="h-[400px] md:h-auto relative bg-chocolate-50 overflow-hidden">
                        {recipe.image_url ? (
                            <img 
                                src={recipe.image_url} 
                                alt={recipe.name} 
