                                                <div className="absolute top-2 right-2 bg-amber-500 text-chocolate-950 text-[9px] font-black w-6 h-6 rounded-lg flex items-center justify-center shadow-lg border-2 border-white">
                                                    {inCart.quantity}
                                                </div>
                                            )}
                                        </motion.button>
