                                >
                                    Initiate Settlement
                                </Button>
                            </div>
                        </motion.div>
                    </>
                )}

                {showPayment && (
                    <motion.div
                        className="fixed inset-0 bg-chocolate-950/80 backdrop-blur-xl z-[100] flex items-center justify-center p-6"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={closePaymentModal}
                    >
                        <motion.div
                            className="bg-white rounded-[3rem] w-full max-w-xl overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.3)] border border-white/10 max-h-[90vh] overflow-y-auto"
                            initial={{ scale: 0.9, y: 20 }}
                            animate={{ scale: 1, y: 0 }}
                            onClick={e => e.stopPropagation()}
                        >
                            <AnimatePresence mode="wait">
                                {paymentSuccess ? (
                                    <motion.div
                                        key="success"
                                        initial={{ opacity: 0, scale: 0.8 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        className="p-16 text-center"
                                    >
                                        <div className="w-24 h-24 bg-green-500 rounded-full flex items-center justify-center mx-auto mb-10 shadow-[0_0_40px_rgba(34,197,94,0.3)]">
                                            <Check className="w-12 h-12 text-white stroke-[4px]" />
                                        </div>
                                        <h2 className="text-4xl font-black text-chocolate-950 mb-4 tracking-tighter uppercase">Invoice Settled</h2>
                                        <p className="text-chocolate-500 font-bold max-w-xs mx-auto text-sm">Transaction fingerprint generated. Inventory manifests updated in real-time.</p>
                                    </motion.div>
                                ) : (
                                    <motion.div key="form">
                                        <div className="p-10 border-b border-chocolate-50 flex items-center justify-between">
                                            <h2 className="text-2xl font-black uppercase text-chocolate-950 tracking-widest">Settlement</h2>
                                            <button onClick={closePaymentModal} className="w-10 h-10 rounded-full bg-white border border-chocolate-100 flex items-center justify-center hover:bg-chocolate-50 transition-all"><X className="w-5 h-5 text-chocolate-900" /></button>
                                        </div>
                                        <div className="p-10 space-y-8">
                                            {/* Amount Display */}
                                            <div className="flex flex-col items-center">
                                                <p className="text-[12px] font-black text-chocolate-400 uppercase tracking-[0.3em] mb-3">Total Payable Amount</p>
                                                <span className="text-5xl font-black text-chocolate-950 tracking-tighter">${cartTotalWithTax.toFixed(2)}</span>
                                            </div>

                                            {/* Payment Method Selection */}
                                            <div className="grid grid-cols-3 gap-4">
                                                {(['CARD', 'CASH', 'TRANSFER'] as const).map(method => (
                                                    <button
                                                        key={method}
                                                        onClick={() => handlePaymentMethodSelect(method)}
                                                        disabled={paymentLoading}
                                                        className={`p-5 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${
                                                            paymentMethod === method
                                                                ? 'border-amber-500 bg-amber-500/5 shadow-inner'
                                                                : 'border-chocolate-100 bg-white hover:border-chocolate-200'
                                                        } ${paymentLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                                                    >
                                                        <div className={`p-3 rounded-xl ${paymentMethod === method ? 'bg-amber-500 text-chocolate-950' : 'bg-chocolate-50 text-chocolate-400'}`}>
                                                            {method === 'CARD' ? <CreditCard className="w-5 h-5" /> : method === 'CASH' ? <DollarSign className="w-5 h-5" /> : <Zap className="w-5 h-5" />}
                                                        </div>
                                                        <span className={`text-[10px] font-black uppercase tracking-widest ${paymentMethod === method ? 'text-chocolate-950' : 'text-chocolate-500'}`}>{method}</span>
                                                    </button>
                                                ))}
                                            </div>

                                            {/* Error Display */}
                                            {paymentError && (
                                                <motion.div
                                                    initial={{ opacity: 0, y: -10 }}
                                                    animate={{ opacity: 1, y: 0 }}
                                                    className="flex items-center gap-3 p-4 bg-red-50 border border-red-200 rounded-xl"
                                                >
                                                    <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0" />
                                                    <p className="text-sm text-red-700">{paymentError}</p>
                                                </motion.div>
                                            )}

                                            {/* Stripe Card Payment Form */}
                                            {paymentMethod === 'CARD' && (
                                                <div className="border-t border-chocolate-100 pt-6">
                                                    {paymentLoading ? (
                                                        <div className="flex flex-col items-center justify-center py-12">
                                                            <Loader2 className="w-10 h-10 text-amber-500 animate-spin mb-4" />
                                                            <p className="text-chocolate-500 font-bold text-sm">Initializing secure payment...</p>
                                                        </div>
                                                    ) : clientSecret ? (
                                                        <Elements
                                                            stripe={stripePromise}
                                                            options={{
                                                                clientSecret,
                                                                appearance: {
                                                                    theme: 'stripe',
                                                                    variables: {
                                                                        colorPrimary: '#f59e0b',
                                                                        colorBackground: '#ffffff',
                                                                        colorText: '#1f1f1f',
                                                                        colorDanger: '#ef4444',
                                                                        fontFamily: 'system-ui, sans-serif',
                                                                        borderRadius: '12px',
                                                                    },
                                                                },
                                                            }}
                                                        >
                                                            <StripePaymentForm
                                                                amount={cartTotalWithTax}
                                                                onSuccess={handleStripeSuccess}
                                                                onCancel={closePaymentModal}
                                                            />
                                                        </Elements>
                                                    ) : (
                                                        <div className="text-center py-8">
                                                            <p className="text-chocolate-400 text-sm mb-4">Click the button below to load the payment form</p>
                                                            <Button
                                                                onClick={initiateStripePayment}
                                                                className="bg-amber-500 text-chocolate-950 font-bold px-8 py-3 rounded-xl"
                                                            >
                                                                Load Secure Payment
                                                            </Button>
                                                        </div>
                                                    )}
                                                </div>
                                            )}

                                            {/* Cash/Transfer Payment Button */}
                                            {(paymentMethod === 'CASH' || paymentMethod === 'TRANSFER') && (
                                                <Button
                                                    className="w-full bg-chocolate-950 text-amber-500 font-black py-8 rounded-[2rem] text-lg uppercase tracking-[0.2em] group relative overflow-hidden active:scale-95 disabled:opacity-50"
                                                    onClick={processCashPayment}
                                                    disabled={paymentLoading}
                                                >
                                                    <span className="relative z-10 flex items-center justify-center gap-4">
                                                        {paymentLoading ? (
                                                            <>
                                                                <Loader2 className="w-6 h-6 animate-spin" />
                                                                Processing...
                                                            </>
                                                        ) : (
                                                            <>
                                                                {paymentMethod === 'CASH' ? 'Confirm Cash Payment' : 'Confirm Transfer'}
                                                                <ChevronRight className="w-6 h-6 group-hover:translate-x-1 transition-transform" />
                                                            </>
                                                        )}
                                                    </span>
                                                </Button>
                                            )}
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
};

export default SalesPage;

